UPDATE contents SET body = 'والحمدُ للهِ رَبِّ العَالَمِين' WHERE id = 1658;
-- p15
UPDATE contents SET body = 'كقوله تعالى: ﴿ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱذۡكُرُواْ ٱللَّهَ ذِكۡرٗا كَثِيرٗا ٤١ وَسَبِّحُوهُ بُكۡرَةٗ وَأَصِيلًا ﴾ [الأحزاب: ٤١، ٤٢]، وقوله عز وجل: ﴿ فَٱذۡكُرُونِيٓ أَذۡكُرۡكُمۡ ﴾ [البقرة: ١٥٢]، وقوله جَلَّ وَعَلَا: ﴿ وَٱذۡكُر رَّبَّكَ فِي نَفۡسِكَ تَضَرُّعٗا وَخِيفَةٗ وَدُونَ ٱلۡجَهۡرِ مِنَ ٱلۡقَوۡلِ بِٱلۡغُدُوِّ وَٱلۡأٓصَالِ وَلَا تَكُن مِّنَ ٱلۡغَٰفِلِينَ ﴾ [الأعراف: ٢٠٥].' WHERE id = 1677;
-- p16
UPDATE contents SET body = 'ورُوِيَ عن معاذِ بْنِ جبلٍ رضي الله عنه مرفوعًا: «ما عَمِلَ آدمِيٌّ قطُّ عملًا أنْجَى له مِن عذابِ اللهِ؛ مِنْ ذِكْرِ اللهِ تعالى».' WHERE id = 1682;
-- p19
UPDATE contents SET body = 'عن سَمُرةَ بنِ جُنْدُبٍ رضي الله عنه عن النبيِّ ﷺ قال: «إذا حَدَّثتُكُم حديثًا؛ فلا تَزِيدُنَّ عَلَيَّ» الحديث، ومعناه يشملُ النهي عن الزيادة في لفظ الذكر تعبُّدًا.' WHERE id = 1688;
-- p21
UPDATE contents SET body = 'فَمِن هُنا شَبَّه الصحابةُ تعليمَ النبيِّ ﷺ إيَّاهم بعضَ الأدعيةِ بتعليمه إيَّاهم القرآن، ووجه الشبه هنا أنها تُحفَظ وتُنقَل نقلًا حرفيًّا، ولا تُغَيَّر ولا تُبَدَّل.' WHERE id = 1692;
UPDATE contents SET body = 'ففي حديث الاستخارة: «كان رسول الله ﷺ يعلمنا الاستخارةَ في الأمور كلِّها كما يعلمنا السورةَ من القرآن»، وقال ابنُ مسعودٍ رضي الله عنه: «عَلَّمَني رسُولُ الله ﷺ التشهُّدَ، وكَفِّي بين كَفَّيْهِ، كما يُعَلِّمُني السورةَ من القرآن».' WHERE id = 1693;
-- p22
UPDATE contents SET body = 'وفي حديث ابن عبَّاسٍ رضي الله عنهما، أنَّ رسولَ اللهِ ﷺ كان يعلمهم هذا الدعاء كما يعلمهم السورةَ من القرآن، يقول: «اللهم إني أعوذ بك من عذاب جهنم...» الحديث.' WHERE id = 1694;
-- p24
UPDATE contents SET body = 'وقال القاضي عياض رحمه الله (ت ٥٤٤هـ): «إنَّ الله أَذِنَ في دعائه، وعَلَّمَ الدعاء في كتابه لخليقته، وعَلَّمَ النبيُّ ﷺ الدعاءَ لأمته، واجتمعت فيه ثلاثةُ أشياءَ: العلمُ بالتوحيد، والعلمُ باللغة، والنصيحة لأُمَّته، فلا ينبغي لأحدٍ أن يعدِلَ عن دعائه ﷺ.

وقد احتال الشيطانُ للناس في هذا المقام، فَقَيَّضَ لهم قوم سوءٍ يخترعون لهم أدعيةً يشتغلون بها عن الاقتداء بالنبي ﷺ، وأشد ما في الحال أنهم ينسبونها إلى الأنبياء والصالحين، فيقولون: (دعاء آدم، دعاء نوح، دعاء يونس، دعاء أبي بكر الصديق)! فاتقوا الله في أنفسكم، ولا تشتغلوا من الحديث إلا بالصحيح منه».اهـ.' WHERE id = 1012;
-- p26
UPDATE contents SET body = 'وقال ذَهَبِيُّ العصرِ العلَّامةُ المجدد عبدُ الرحمن بن يحيى المُعَلِّمي اليماني (ت ١٣٨٦هـ) رحمه الله: «وما أخسرَ صفقةَ مَن يَدَعُ الأدعيةَ الثابتة في كتابِ الله عز وجل أو في سُنَّةِ رسوله ﷺ فلا يكادُ يدعو بها! ثم يعمَدُ إلى غيرها فيتحرَّاه ويواظب عليه، أليس هذا من الظلم والعدوان؟!».' WHERE id = 1699;
-- p29
UPDATE contents SET body = 'قَالَ اللهُ تعالى:
QuranText[(33:41:42)]' WHERE id = 1228;
-- p31
UPDATE contents SET body = 'واعلم -وفقك الله- أنَّ العلماء اختلفوا في تحديد وقت أذكار الصباح والمساء على أقوال؛ أرجحها -والله تعالى أعلم- أنَّ وقت أذكار الصباح يبدأ بطلوع الفجر الصادق إلى طلوع الشمس، وهذا وقتها الفاضل.

ثم يمتد وقتها -تبَعًا- إلى ارتفاع الشمس بمقدار رمح (ويقدر بحوالي ١٦ دقيقة)، وهذا وقتها المفضول، وهو أول وقت صلاة الضحى.

ومن فاته هذان الوقتان فليأت بها إلى ما قبل أذان الظهر بوقت يسير.' WHERE id = 1232;
-- p32
UPDATE contents SET body = 'أما أذكار المساء فيبدأُ وقتها من دخول وقت صلاة العصر إلى غروب الشمس، ويمتد -تبَعًا- إلى أن يمضي ثلث الليل، وقيل: نصفه.' WHERE id = 1235;
-- p42
UPDATE contents SET body = 'أو يقول: لا إله إلا اللهُ وحدَه، لا شريكَ له، له الملكُ، وله الحمدُ، وهو على كُلِّ شيءٍ قديرٌ [مئةَ مَرَّةٍ]' WHERE id = 1236;
-- p43
UPDATE contents SET body = 'فإذا قام عن مجلسه ختمه بكَفَّارةِ المجلس:' WHERE id = 1234;
-- p59
UPDATE contents SET body = 'الخامس: أن يستحضر قول أبي سعيد الخدري رضي الله عنه: «إذا أصبح ابنُ آدَمَ فإنَّ الأعضاء كُلَّها تُكَفِّرُ اللسان، تقول: اتق الله فينا فإنما نحنُ بِكَ، فإن استقمت استقمنا، وإن اعْوجَجْتَ اعْوجَجْنا». [موقوف حسن، له حكم المرفوع]

وقوله ﷺ: «أكثر خطايا ابن آدم في لسانه». [جَيِّدٌ]' WHERE id = 1243;
-- p64
UPDATE contents SET body = 'السابع: أن يجتهد في الجمع في يوم واحد بين صوم تطوّع، وعيادة مريض، وتشييع جنازة، وإطعام مسكين؛ فقد قال أبو هريرة رضي الله عنه: قال رسول الله ﷺ: «من أصبح منكم اليوم صائمًا؟»، قال أبو بكر: أنا. قال: «من عاد منكم اليوم مريضًا؟»، قال أبو بكر: أنا. قال: «من شَهِدَ منكم اليوم جِنازَةً؟»، قال أبو بكر: أنا. قال: «فَمَن أطعم اليوم مسكينًا؟»، قال أبو بكر: أنا. فقال رسول الله ﷺ: «ما اجتمعت هذه الخصالُ في رَجُلٍ في يومٍ؛ إلَّا دَخَلَ الجَنَّةَ». [مسلم]' WHERE id = 1246;
-- p65
UPDATE contents SET body = 'التاسع: أن يُبادِرَ بكتابة وصيته بشيء من ماله -ثلث أو أقل- إذا كان له مال كثير، وورثته أغنياء، فيُوصِي به إلى أقربائه من غير الوارثين، أو لجهة من جهات الخير.

وإذا كان له مال عند أحد، أو كان عليه دَيْن أو عنده وديعة، أو عليه حقوق يخشى أن تضيع على أصحابها بموته؛ فيجب عليه أن يُوصِيَ بذلك حتى لا يؤاخذه الله بها، وكذا له أن يُوصِيَ بالعهد إلى مَن ينظر في شأن أولاده الصغار إلى بلوغهم.' WHERE id = 1248;
-- p66
UPDATE contents SET body = 'العاشر: أن يستحضر قول الله تَبَارَكَ وَتَعَالَى: ﴿ وَحَاقَ بِـَٔالِ فِرۡعَوۡنَ سُوٓءُ ٱلۡعَذَابِ ٤٥ ٱلنَّارُ يُعۡرَضُونَ عَلَيۡهَا غُدُوّٗا وَعَشِيّٗا ﴾ الآيتين [غافر: ٤٥، ٤٦].

عن ميمون بن مسيرة، قال: كانت لأبي هريرة رضي الله عنه صيحتان في كل يوم؛ أوَّلَ النهار وآخِرَه، يقول: «ذهب الليل، وجاءَ النهار، وعُرِضَ آل فرعون على النار»، فلا يسمعه أحدٌ إلا استعاذ بالله من النار.' WHERE id = 1249;
-- p72
UPDATE contents SET body = '١- اللهم لك الحمدُ، أنت كَسَوْتَنِيهِ، أسألُكَ خيرَه، وخيرَ ما صُنِعَ له، وأعوذُ بِكَ مِنْ شَرِّه، وشَرِّ ما صُنِعَ له' WHERE id = 64;
-- p73
UPDATE contents SET body = '٣- اِلْبَسْ جَديدًا، وَعِشْ حميدًا، وَمُتْ شهيدًا، ويَرزقُكَ اللهُ قُرَّةَ عينٍ في الدنيا والآخرة' WHERE id = 69;
-- p78
UPDATE contents SET body = 'أو: اللهم أَجِرْنِي من الشيطان الرجيم' WHERE id = 897;
-- p89
UPDATE contents SET body = '٢- لَتُسَوُّنَّ صُفُوفَكم، أو لَيُخَالِفَنَّ اللهُ بَينَ وُجُوهِكُم.' WHERE id = 1016;
-- p93
UPDATE contents SET body = '٣- سبحانَك اللهمَّ وبحَمْدِكَ، وتبارك اسمُكَ، وتعالى جَدُّكَ، ولا إله غيرُكَ' WHERE id = 909;
UPDATE contents SET body = '٥- الحمدُ للهِ حمدًا كثيرًا طَيِّبًا مُبارَكًا فيه' WHERE id = 911;
-- p94
UPDATE contents SET body = '١- اللهم لك الحمدُ، أنت نورُ السماواتِ والأرضِ وَمَنْ فِيهنَّ، ولك الحمدُ، أنت قَيِّمُ السماواتِ والأرضِ وَمَنْ فِيهنَّ، ولك الحمدُ، أنتَ مَلِكُ السماواتِ والأرضِ وَمَنْ فِيهنَّ، ولك الحمدُ، أنتَ الحقُّ، ووعدُكَ الحقُّ، وقولُكَ حَقٌّ، وَلِقاؤُكَ حَقٌّ، والجنَّةُ حَقٌّ، والنَّارُ حَقٌّ، والسَّاعةُ حَقٌّ، والنبيُّونَ حَقٌّ، ومُحَمَّدٌ حَقٌّ، اللهُمَّ لَكَ أسلمتُ، وعليك توكَّلْتُ، وبِكَ آمنتُ، وإليكَ أنَبْتُ، وبِكَ خَاصَمْتُ، وإليكَ حاكَمْتُ، أنتَ رَبُّنا، وإليكَ المصير، فاغفِرْ لي ما قَدَّمْتُ، وما أخَّرْتُ، وما أسررْتُ، وما أعلنتُ، وما أنتَ أَعْلَمُ به مِنِّي، أنتَ المُقَدِّمُ، وأنتَ المؤخِّرُ، أنت إلهي، لاَ إله إلا أنت، ولا حول ولا قوَّةَ إلَّا بِكَ' WHERE id = 912;
-- p95
UPDATE contents SET body = 'اللهم اغفِرْ لي، واهدِنِي، وارزقني، وعافني [عشرًا]' WHERE id = 1209;
UPDATE contents SET body = 'اللهم إني أعوذُ بِكَ من الضِّيقِ يوم الحساب [عشرًا]' WHERE id = 1210;
-- p96
UPDATE contents SET body = 'أو: أعوذ بالله من الشيطانِ الرجيم من هَمْزِه ونَفْخِهِ ونَفْثِه' WHERE id = 918;
UPDATE contents SET body = 'أو: أعوذ بالله السميع العليم من الشيطانِ الرجيمِ، مِنْ هَمْزِهِ ونَفْخِهِ ونِفْثِه' WHERE id = 919;
-- p98
UPDATE contents SET body = '٧- اللهم لك ركعتُ، وبك آمنتُ، ولك أسلمتُ، أنتَ رَبِّي، خَشَعَ لَكَ سَمْعِي وبَصَرِي، ومُخِّي وعَظْمي وعَصَبِي، وما استَقَلَّتْ به قَدَمِي للهِ رَبِّ العالمين' WHERE id = 926;
-- p101
UPDATE contents SET body = '٦- اللهم اغفِرْ لي ما أسررتُ، وما أعلنتُ' WHERE id = 108;
UPDATE contents SET body = '٧- اللهم اغفِرْ لي ذنبي كُلَّه، ودِقَّه وجِلَّهُ، وأوَّلَه وآخِرَه، وعلانِيَتَهُ وسِرَّه' WHERE id = 109;
UPDATE contents SET body = '٨- اللهم إني أعوذُ بِرِضَاكَ مِن سَخَطِكَ، وأعوذُ بمعافاتِكَ مِنْ عقوبَتِكَ، وأعوذُ بك منكَ، لا أُحصِي ثناءً عليك، أنتَ كما أثنيتَ على نفسِكَ' WHERE id = 110;
UPDATE contents SET body = '٩- اللهم إني ظلمتُ نفسي ظُلمًا كثيرًا، ولا يَغفِرُ الذنوبَ إلَّا أنتَ، فاغفِرْ لي مغفرةً مِن عندك، وارحمني إنك أنت الغفورُ الرحيم' WHERE id = 111;
-- p102
UPDATE contents SET body = '١١- سَجَدَ لك سَوادي وخيالي، وآمَنَ بك فؤادي، أبوءُ بنعمتِكَ عَلَيَّ، هَذِي يَدِي، وما جَنَيْتُ عَلَى نفسي' WHERE id = 113;
UPDATE contents SET body = '١٣- سبحانك اللهم وبحمدك، لا إله إلا أنتَ' WHERE id = 115;
UPDATE contents SET body = '٢- اللهم اغفِرْ لي، وارحمني، واجْبُرْنِي، وارْفَعْنِي، واهْدِنِي، وعافِنِي، وارزقني' WHERE id = 117;
UPDATE contents SET body = 'وكان صلى الله عليه وسلم يقول: «أقرَبُ ما يكونُ العبدُ من رَبِّه وَهُوَ ساجِدٌ، فأكثِروا الدعاءَ فيه».' WHERE id = 1216;
-- p103
UPDATE contents SET body = '١- سَجَدَ وجهي لِلَّذي خَلَقَهُ، وشَقَّ سمعَه وبَصَرَه بحولِه وقُوَّتِه' WHERE id = 118;
UPDATE contents SET body = '٢- اللَّهُمَّ اكتُبْ لي بها عِنْدَكَ أجرًا، وَضَعْ عَنِّي بِها وِزْرًا، واجْعَلْها لي عِنْدَكَ ذُخْرًا، وَتَقَبَّلْها مِنِّي كما تَقَبَّلْتَها مِنْ عَبْدِكَ داودَ' WHERE id = 119;
-- p104
UPDATE contents SET body = '«اللهمَّ إنَّا نستعينُكَ ونستغفِرُكَ، ولا نَكْفُرُكَ، ونُؤمِنُ بِكَ، ونخلعُ مَنْ يَفْجُرُكَ، اللهمَّ إيَّاكَ نعبدُ، ولك نُصَلِّي ونَسْجُدُ، وإليكَ نسْعَى ونَحْفِدُ، نرجو رحمتَكَ، ونخشى عذابَكَ، إنَّ عذَابَكَ الجِدَّ بالكُفَّارِ مُلْحِقٌ' WHERE id = 155;
UPDATE contents SET body = 'وصَحَّ أنَّ الصحابةَ رضي الله عنهم كانوا يَزيدون عليه في النصف الثاني من رمضان، ومن ذلك دعاء عمر رضي الله عنه:' WHERE id = 1219;
-- p105
UPDATE contents SET body = 'اللهمَّ اغْفِرْ للمؤمنين والمؤمنات، والمسلمين والمسلمات، وأَصْلِحْ ذاتَ بَيْنِهمْ، وأَلِّفْ بَيْنَ قلوبِهم، واجْعَلْ في قلوبِهِمُ الإيمانَ والحِكمةَ، وثَبِّتْهم على مِلَّةِ رَسُولِ اللهِ صلى الله عليه وسلم، وأَوْزِعْهُم أن يُوفُوا بعَهْدِكَ الَّذي عاهدتَهم عليه، وانصُرْهم على عَدُوِّكَ وعَدُوِّهم، إلَهَ الحَقِّ، واجْعَلْنا مِنْهُم»' WHERE id = 1220;
-- p107
UPDATE contents SET body = '٢- التحيَّاتُ المباركاتُ الصلواتُ الطيِّباتُ للهِ، السلامُ عليكَ أيها النبيُّ ورحمةُ اللهِ وبركاتُه، السلامُ علينا وعلى عبادِ اللهِ الصالحين، أشهدُ أن لا إله إلا اللهُ، وأشهدُ أنَّ محمدًا رسولُ اللهِ' WHERE id = 936;
UPDATE contents SET body = '٣- التحيَّاتُ للهِ، والصلواتُ والطيباتُ، السلامُ عليكَ أيُّها النبيُّ ورحمةُ اللهِ وبركاتُه، السلامُ علينا وعلى عبادِ اللهِ الصالحين، أشهدُ أنْ لا إله إلا اللهُ وحدَه لا شريكَ له، وأشهدُ أنَّ محمدًا عبدُه ورسولُه' WHERE id = 937;
UPDATE contents SET body = '٤- التحيَّاتُ الطيباتُ الصلواتُ للهِ، السلامُ عليكَ أيُّها النبيُّ ورحمةُ اللهِ وبركاتُه، السلامُ علينا وعلى عبادِ اللهِ الصالحين، أشهدُ أنْ لا إله إلا اللهُ وحدَه لا شريكَ له، وأشهدُ أنَّ محمدًا عبدُهُ ورسولُه' WHERE id = 938;
UPDATE contents SET body = 'وفي روايةٍ: «عبدُهُ ورسولُه».' WHERE id = 1222;
-- p108
UPDATE contents SET body = '٥- التحيَّاتُ للهِ، الزاكياتُ للهِ، الطيباتُ للهِ، الصلواتُ للهِ، السلامُ عليكَ أيُّها النبيُّ ورحمةُ اللهِ وبركاتُه، السلامُ علينا وعلى عبادِ اللهِ الصالحين، أشهدُ أن لا إله إلا اللهُ، وأشهدُ أنَّ محمدًا عبدُه ورسولُه' WHERE id = 939;
-- p109
UPDATE contents SET body = '١- اللهمَّ صَلِّ على محمدٍ وعلى آلِ محمدٍ، كما صلَّيتَ على إبراهيمَ وعلى آلِ إبراهيمَ، إنَّكَ حميدٌ مجيدٌ، اللهمَّ بارِكْ على محمدٍ وعلى آلِ محمدٍ، كما باركتَ على إبراهيمَ وعلى آلِ إبراهيمَ، إنَّكَ حميدٌ مجيدٌ' WHERE id = 121;
-- p110
UPDATE contents SET body = '٢- اللهمَّ صَلِّ على محمدٍ وعلى أهلِ بيتِه، وعلى أزواجِهِ وذُرِّيَّتِه، كما صلَّيتَ على آلِ إبراهيمَ، إنَّكَ حميدٌ مجيدٌ، وبارِكْ على محمدٍ وعلى آلِ بيتِه، وعلى أزواجِه وذريتِه، كما باركتَ على آلِ إبراهيمَ، إنَّكَ حميدٌ مجيدٌ' WHERE id = 940;
UPDATE contents SET body = '٣- اللهمَّ صَلِّ على محمدٍ، وعلى آلِ محمدٍ، كما صَلَّيتَ على إبراهيمَ وآلِ إبراهيمَ، إنَّكَ حميدٌ مجيدٌ، وبارِكْ على محمدٍ، وعلى آلِ محمدٍ، كما باركتَ على إبراهيمَ وآلِ إبراهيمَ، إنَّكَ حميدٌ مجيدٌ' WHERE id = 941;
-- p111
UPDATE contents SET body = '٦- اللهم صَلِّ على محمدٍ وعلى أزواجِهِ وذُرِّيَّتِهِ، كما صَلَّيْتَ على آلِ إبراهيمَ، وبارِكْ على محمدٍ وعلى أزواجِهِ وذُرِّيتِهِ، كما باركتَ على آلِ إبراهيمَ، إنَّكَ حميدٌ مجيدٌ' WHERE id = 122;
-- p112
UPDATE contents SET body = '٢- اللهم إني أعوذُ بك من عذابِ القبرِ، وأعوذُ بك من فتنةِ المسيحِ الدجالِ، وأعوذُ بك من فتنةِ المحيا والمماتِ، اللهم إنِّي أعوذُ بك من المأْثَمِ والمَغْرَم' WHERE id = 124;
-- p113
UPDATE contents SET body = '٣- اللهم إنِّي أعوذُ بك مِن شَرِّ ما عَمِلْتُ، ومِن شر ما لم أعمل' WHERE id = 125;
UPDATE contents SET body = '٤- اللهم إني أسألُكَ الجنَّةَ، وأعوذُ بِكَ من النَّارِ' WHERE id = 126;
UPDATE contents SET body = '٥- اللهم إنِّي ظلمتُ نفسي ظُلْمًا كثيرًا، ولا يغفِرُ الذنوبَ إلَّا أنتَ، فاغفِرْ لي مغفِرَةً مِنْ عِنْدِكَ، وارْحَمْنِي إنَّك أنتَ الغفورُ الرحيمُ' WHERE id = 127;
UPDATE contents SET body = '٦- اللهم حاسِبْنِي حسابًا يسيرًا' WHERE id = 128;
UPDATE contents SET body = '٧- اللهم إنِّي أسألُكَ يا اللهُ الواحدُ الأحدُ الصَّمَدُ، الذي لم يَلِدْ ولَمْ يُولَدْ، ولَمْ يَكُنْ له كُفُوًا أحدٌ، أن تَغْفِرَ لي ذُنُوبِي، إنَّكَ أنتَ الغفورُ الرَّحيمُ' WHERE id = 129;
-- p114
UPDATE contents SET body = '٨- اللهم إنِّي أسألُكَ بأنَّ لَكَ الحمدَ، لا إلهَ إلَّا أنتَ وحدَكَ، لا شريكَ لك، المنَّانُ، يا بديعَ السَّماواتِ والأرضِ، يا ذا الجلالِ والإكرامِ، يا حَيُّ يا قَيُّومُ، إنِّي أسألُكَ الجَنَّةَ، وأعوذُ بِكَ من النَّارِ' WHERE id = 130;
UPDATE contents SET body = '٩- اللهم إنِّي أسألُكَ من الخيرِ كُلِّه، عاجِلِهِ وآجِلِه، ما عَلِمْتُ منه وما لم أعلمْ، وأعوذُ بك من الشَّرِّ كُلِّه، عاجِلِهِ وآجِلِه، ما عَلِمْتُ منه وما لَمْ أعلمْ، اللهم إنِّي أسألُكَ الجَنَّةَ، وما قَرَّبَ إليها مِنْ قَوْلٍ أو عَمَلٍ، وأعوذُ بكَ من النَّارِ، وما قَرَّبَ إليها من قولٍ أو عملٍ، اللهم إنِّي أسألُكَ من خيرِ ما سألَكَ عبدُكَ ورسولُكَ محمدٌ صلى الله عليه وسلم، وأعوذُ بِكَ من شَرِّ ما استعاذَكَ منه عبدُكَ ورسولُكَ محمدٌ صلى الله عليه وسلم، وأسألُكَ ما قَضَيْتَ لي مِنْ أمرٍ أن تجعلَ عاقِبَتَهُ لي رَشَدًا' WHERE id = 131;
-- p115
UPDATE contents SET body = '١٢- اللهم اغفِرْ لي ما قَدَّمْتُ، وما أَخَّرْتُ، وما أسررتُ، وما أعلنتُ، وما أسرفتُ، وما أنتَ أعلمُ به منِّي، أنتَ المُقَدِّمُ، وأنتَ المؤخِّرُ، لا إله إلَّا أنت' WHERE id = 133;
-- p116
UPDATE contents SET body = '٢- لا إلهَ إلا اللهُ وحدَه لا شريكَ له، له المُلْكُ، وله الحمدُ، وهُوَ على كلِّ شيءٍ قديرٌ، لا حولَ ولا قوَّةَ إلَّا باللهِ، لا إلهَ إلَّا اللهُ، ولا نعبدُ إلَّا إيَّاهُ، له النِّعمةُ، وله الفضلُ، وله الثناءُ الحَسَنُ، لا إلهَ إلا اللهُ، مُخلِصِينَ له الدِّينَ ولو كَرِهَ الكافرون' WHERE id = 134;
UPDATE contents SET body = '٣- أستغفِرُ اللهَ، أستغفرُ اللهَ، اللهمَّ أنتَ السلامُ، ومنكَ السلامُ، تباركتَ يا ذا الجلالِ والإكرامِ' WHERE id = 135;
-- p117
UPDATE contents SET body = '٤- لا إلهَ إلَّا اللهُ وحدَه لا شريكَ له، له المُلْكُ، وله الحمدُ، وهوَ على كُلِّ شيءٍ قديرٌ، اللهمَّ لا مانِعَ لما أعطيتَ، ولا مُعْطِيَ لما منعتَ، ولا ينفعُ ذا الجَدِّ منكَ الجَدُّ' WHERE id = 136;
UPDATE contents SET body = '٧- اللهمَّ أعِنِّي على ذِكْرِكَ، وَشُكْرِكَ، وحُسْنِ عبادتِكَ' WHERE id = 139;
UPDATE contents SET body = '٨- رَبِّ قِنِي عذابَكَ يومَ تجمعُ -أو: تَبْعَثُ- عبادَكَ' WHERE id = 140;
UPDATE contents SET body = '٩- اللهمَّ إنِّي أعوذُ بكَ من الكُفْرِ والفقرِ وعذابِ القبرِ' WHERE id = 141;
UPDATE contents SET body = '١٠- اللهمَّ لا تُخْزِني يومَ القيامةِ' WHERE id = 1250;
-- p118
UPDATE contents SET body = '١١- اللهمَّ إنِّي أعوذُ بكَ من الجُبْنِ، وأعوذُ بِكَ أن أُرَدَّ إلى أرذلِ العُمُرِ، وأعوذُ بكَ من فتنةِ الدنيا، وأعوذُ بِكَ من عذابِ القبرِ' WHERE id = 143;
UPDATE contents SET body = '١٢- اللهمَّ إنِّي أسألُكَ فِعْلَ الخيراتِ، وتَرْكَ المُنكراتِ، وحُبَّ المساكينِ، وأن تَغفِرَ لي وتَرْحَمَنِي، وتتوبَ عَلَيَّ، وإذا أردتَ بعبادِكَ فِتنةً فاقبِضْني إليكَ غَيْرَ مَفْتُونٍ' WHERE id = 144;
UPDATE contents SET body = '١٣- سُبحانَ اللهِ، والحمدُ للهِ، واللهُ أكبرُ [٣٣ مرة]' WHERE id = 947;
UPDATE contents SET body = 'أو: «سبحانَ اللهِ» (٣٣)، «الحمدُ للهِ» (٣٣)، «اللهُ أكبرُ» (٣٣)، ثُمَّ يقول: «لا إلهَ إلَّا اللهُ وحدَه لا شريكَ له، له المُلْكُ، وله الحمدُ، وهُوَ على كُلِّ شيءٍ قديرٌ»' WHERE id = 948;
UPDATE contents SET body = 'ثُمَّ يقول:' WHERE id = 1196;
-- p119
UPDATE contents SET body = '١٤- سُبحانكَ اللهمَّ وبحمدِكَ، أستغفِرُكَ، وأتوبُ إليكَ' WHERE id = 148;
UPDATE contents SET body = 'أو: «سُبحانَ اللهِ» (٢٥)، «الحمدُ للهِ» (٢٥)، «لا إلهَ إلَّا اللهُ» (٢٥)، «اللهُ أكبرُ» (٢٥)' WHERE id = 952;
UPDATE contents SET body = '- يَعْقِدُهُنَّ بأنامِلِه.' WHERE id = 1197;
