UPDATE contents SET body = 'لا إلهَ إلَّا اللهُ وحدَه لا شريكَ له، له المُلْكُ، وله الحمدُ، يُحيي ويُميتُ، وهو على كُلِّ شيءٍ قديرٌ [عشر مرَّات]' WHERE id = 149;
UPDATE contents SET body = 'لا إلهَ إلَّا اللهُ وحدَه لا شريكَ له، له المُلْكُ، وله الحمدُ، يُحيي ويُميتُ، وهو على كُلِّ شيءٍ قديرٌ [عشر مرَّات]' WHERE id = 962;
UPDATE contents SET body = 'ذكر الله تعالى عقب صلاة الصبح
(وهو أشرَفُ أوقاتِ الذِّكرِ في النَّهارِ)' WHERE id = 1198;
-- p121
UPDATE contents SET body = 'سُبحانَ الملكِ القُدُّوسِ،
سُبحانَ الملكِ القُدُّوسِ،
سُبحانَ الملكِ القُدُّوسِ.
(هكذا ثلاثًا، ويمدُّ بها صوتَه، ويرفعُ في الثالثة)' WHERE id = 151;
UPDATE contents SET body = 'اللهمَّ إنِّي أعوذُ برضاكَ من سَخَطِكَ، وبمُعافاتِكَ من عقوبتِكَ، وأعوذُ بكَ منكَ، لا أُحصي ثناءً عليكَ، أنتَ كما أثنيتَ على نفسِكَ' WHERE id = 152;
UPDATE contents SET body = 'ما يقول بعد صلاة الوِتر' WHERE id = 1202;
UPDATE contents SET body = 'إذا سَلَّمَ من الوِتر قال:' WHERE id = 1203;
-- p122
UPDATE contents SET body = 'في عيد الفِطر: أول وقت تكبير الفطر إذا غابتِ الشمسُ من ليلةِ الفطر، وحينئذٍ يُستحب إظهار التكبير المطلق في المساجد والمنازل والطرقات؛ لقوله تعالى: ﴿ وَلِتُكۡمِلُواْ ٱلۡعِدَّةَ وَلِتُكَبِّرُواْ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمۡ وَلَعَلَّكُمۡ تَشۡكُرُونَ ﴾ [البقرة: ١٨٥].' WHERE id = 1023;
UPDATE contents SET body = 'وفي عيد الأضحى: يكبر من بعد صلاة الفجر يوم عرفة إلى ما بعد صلاة العصر من آخِرِ أيامِ التشريق، والتكبير فيه مطلق ومقيد، فالمقيَّد عَقِيبَ الصلوات، والمطلق في كلِّ حالٍ في الأسواق، وفي كل مكان.' WHERE id = 1024;
UPDATE contents SET body = 'وقبل صلاة العيد يخرج من بيته، فيكبر جهرًا حتى يأتي المُصَلَّى، ثُمَّ يُكَبِّر حتى يخرجَ الإمامُ.' WHERE id = 1251;
-- p124
UPDATE contents SET body = 'يكبر تكبيرة الإحرام، ثُمَّ يُكَبِّرُ سبعَ تكبيراتٍ في الركعة الأولى قبل القراءة، وفي الثانية يكبر خمس تكبيراتٍ سوى تكبيرة الانتقال.' WHERE id = 1030;
UPDATE contents SET body = 'وبين كلِّ تكبيرتين من هذه التكبيرات: يحمد الله عز وجل، ويُثنِي عليه، ويُصلِّي على النبي صلى الله عليه وسلم، ويدعو.' WHERE id = 1031;
-- p125
UPDATE contents SET body = 'ويُنادَى لصلاة الكسوف بقول: «الصَّلَاةُ جَامِعَةٌ».' WHERE id = 1034;
UPDATE contents SET body = 'يبدأ الإمامُ خُطبَتَهُ بالحمدِ، ويُكْثِرُ من الاستغفار حتى يكونَ أكثرَ كلامِهِ، ويُذَكِّرُهُمْ بقوله تعالى على لسانِ نوحٍ عليه السلام:
QuranText[(71:10:12)]' WHERE id = 1035;
UPDATE contents SET body = 'ثُمَّ يَخْطُبُ الإمامُ النَّاسَ، ويبدأ بحمدِ الله والثناء عليه سبحانه، ثُمَّ يَعِظُ النَّاسَ، ويُذَكِّرُهم بآياتِ الله عز وجل، ويحثُّهم على الدُّعاء والتكبيرِ والصلاةِ والصَّدَقَةِ، ويُحذِّرُهم من أسبابِ غضبِ الله وعقابِه.' WHERE id = 1254;
-- p126
UPDATE contents SET body = 'ويُكثِر من دعاء الكرب، ويُبالِغُ في رَفْعِ يديه، ويدعو الله عز وجل في تضرُّعٍ وتذلل وافتقارٍ ومسكنة بالأدعية التالية:' WHERE id = 1036;
-- p127
UPDATE contents SET body = 'عن أميرِ المؤمنين عليٍّ رضي الله عنه قال: حدَّثَنِي أبو بكرٍ - وصدَقَ أبو بكرٍ رضي الله عنه - قال: سمعتُ رسولَ الله صلى الله عليه وسلم يقول: «ما مِن عبدٍ يُذنبُ ذنبًا فيتوضأ، فيحسن الطُّهور، ثم يقوم فيصلي ركعتين، ثم يستغفر الله لذلك الذنب، إلا غفر الله له»، ثم قرأ هذه الآية:
QuranText[(3:135:135)]' WHERE id = 1044;
-- p128
UPDATE contents SET body = 'قال الإمام ابن العربي رحمه الله: «وفيه استيفاء وجوه الطاعة في التوبة، لأنه نَدِمَ فطهَّر باطنَه، ثم توضَّأ، ثُمَّ صَلَّى، ثُمَّ استغفَر».' WHERE id = 1256;
UPDATE contents SET body = 'الأول: يُستحَبُّ أداءُ صلاةِ التوبة عند عَزْمِه على التوبةِ من الذَّنبِ الذي اقترَفه، والواجِبُ المُبادَرَةُ إلى التوبة بعد وقوعِ المعصيةِ مباشرةً، فإنْ أخَّرَها قُبِلَتْ ما دَامَتْ رُوحُه لم تبلغ الحلقومَ ولم يُغَرْغِرْ.' WHERE id = 1258;
-- p129
UPDATE contents SET body = 'الثاني: تُشرع صلاةُ التوبة في جميع الأوقات حتى أوقات النهي عن الصلاة؛ لأنها من ذوات الأسباب التي تُشْرَع عند وجود سببها.' WHERE id = 1259;
-- p130
UPDATE contents SET body = '١- باسمِكَ اللَّهُمَّ أَحيا وأموتُ' WHERE id = 157;
UPDATE contents SET body = 'اللهمَّ قِنِي عذابَكَ يومَ تَبْعَثُ عِبَادَكَ [ثلاث مرَّات]' WHERE id = 159;
-- p131
UPDATE contents SET body = '٤- باسمِكَ ربِّي وضعتُ جَنْبي، وبكَ أرفعُه، إن أمسكتَ نفسي فارحمْها، وإن أرسلتَها فاحفظْها بما تحفظُ به عِبادَكَ الصالحين' WHERE id = 160;
UPDATE contents SET body = '٥- الحمدُ للهِ الذي أطعمَنا، وسقانا، وكفانا، وآوانا، فكَمْ مِمَّن لا كافِيَ له ولا مُؤْوِي' WHERE id = 161;
UPDATE contents SET body = '٧- لا إلهَ إلَّا اللهُ وحدَه، لا شريكَ له، له المُلْكُ، وله الحمدُ، وَهُوَ على كُلِّ شيءٍ قديرٌ، ولا حَوْلَ ولا قوَّةَ إلَّا باللهِ، سبحانَ اللهِ، والحمدُ للهِ، ولا إلهَ إلا اللهُ، واللهُ أكبرُ' WHERE id = 163;
UPDATE contents SET body = '٨- اللهمَّ أنتَ خلقتَ نفسي، وأنتَ تَوَفَّاها، لكَ مماتُها ومحياها، إن أحييتَها فاحفظْها، وإن أمَتَّها فاغفِرْ لها، اللهمَّ إني أسألُكَ العافيةَ' WHERE id = 164;
UPDATE contents SET body = '٩- أعوذُ بكلماتِ اللهِ التامَّاتِ من شَرِّ ما خَلَقَ' WHERE id = 165;
-- p132
UPDATE contents SET body = '١٠- اللهمَّ فاطِرَ السماواتِ والأرضِ، عالمَ الغيبِ والشَّهادةِ، لا إلهَ إلَّا أنتَ، رَبَّ كُلِّ شيءٍ وَمَليكَهُ، أعوذُ بِكَ مِنْ شَرِّ نَفْسِي، ومِن شَرِّ الشيطانِ وشِرْكِهِ، وأن أقترِفَ على نفسي سُوءًا، أو أجُرَّه إلى مُسْلِمٍ' WHERE id = 166;
UPDATE contents SET body = '١١- اللهمَّ رَبَّ السماواتِ، ورَبَّ الأرضِ، وربَّ العرشِ العظيمِ، ربَّنا ورَبَّ كُلِّ شيءٍ، فالِقَ الحَبِّ والنَّوى، مُنْزِلَ التوراةِ والإنجيلِ والفُرْقَانِ، أعوذُ بِكَ من شَرِّ كُلِّ ذي شَرٍّ أنتَ آخِذٌ بناصِيَتِه، أنتَ الأَوَّلُ فليس قبلَكَ شيءٌ، وأنتَ الآخِرُ فليس بعدَكَ شيءٌ، وأنتَ الظاهِرُ فليس فوقَكَ شيءٌ، وأنتَ الباطِنُ فليس دُونَكَ شيءٌ، اقْضِ عَنَّا الدَّيْنَ، وأغْنِنَا مِنَ الفقرِ' WHERE id = 167;
UPDATE contents SET body = '١٢- اللهمَّ إنِّي أعوذُ بوجهِكَ الكريمِ وكلِماتِكَ التامَّةِ من شَرِّ ما أنتَ آخِذٌ بناصيتِه، اللهمَّ أنتَ تَكشِفُ المَغرَمَ والمأثَمَ، اللهمَّ لا يُهزَمُ جُندُكَ، ولا يُخلَفُ وعدُكَ، ولا ينفعُ ذا الجَدِّ منكَ الجَدُّ، سبحانَكَ اللهمَّ وبحمدِكَ' WHERE id = 168;
-- p133
UPDATE contents SET body = '١٣- باسمِ اللهِ وَضَعْتُ جَنْبِي، اللهمَّ اغفِرْ لي ذَنْبِي، وَأَخْسِئْ شيطاني، وفُكَّ رِهَاني، وَثَقِّلْ مِيزَانِي، واجعلْنِي في النَّدِيِّ الأعلى' WHERE id = 169;
UPDATE contents SET body = '١٤- الحمدُ للهِ الذي كَفَاني وَآواني، وأَطْعَمَني وأَسْقاني، والذي مَنَّ عَلَيَّ فَأَفْضَلَ، والذي أعطاني فأَجْزَلَ، الحمدُ للهِ على كُلِّ حالٍ، اللهمَّ رَبَّ كُلِّ شيءٍ ومَلِيكَهُ، وإلهَ كُلِّ شيءٍ، أعوذُ بِكَ مِنَ النَّارِ' WHERE id = 170;
-- p134
UPDATE contents SET body = '١٦- اللهمَّ إنِّي أسألُكَ رُؤْيا صالحةً، صادِقةً غيرَ كاذِبَةٍ، نافِعَةً غَيْرَ ضَارَّةٍ' WHERE id = 174;
UPDATE contents SET body = '١٧- يقرأ سورة:
QuranText[(109:1:6)]
حتى يخْتِمَها.' WHERE id = 175;
-- p135
UPDATE contents SET body = '١٨- اللهمَّ أَسْلَمْتُ نفسي إليكَ، ووجَّهْتُ وجْهِي إليكَ، وفَوَّضْتُ أمرِي إليكَ، وألجأتُ ظَهْرِي إليكَ، رغبةً ورهبةً إليكَ، لا مَلْجَأَ ولا مَنْجَى مِنْكَ إلا إليكَ، اللهمَّ آمنْتُ بكتابِكَ الذي أنزلْتَ، وبِنَبِيِّكَ الذي أرْسَلْتَ' WHERE id = 176;
-- p136
UPDATE contents SET body = '١- أعوذُ بكلماتِ اللهِ التَّامَّةِ، مِن غَضَبِهِ وعِقابِهِ، ومِنْ شَرِّ عِبادِهِ، ومِن هَمَزاتِ الشَّياطين، وأن يَحْضُرُونِ' WHERE id = 212;
UPDATE contents SET body = '٢- أعوذُ بكلماتِ اللهِ التَّامَّاتِ التي لا يُجاوِزُهُنَّ بَرٌّ ولا فاجِرٌ، مِنْ شَرِّ ما يَنْزِلُ من السماءِ، وما يَعْرُجُ فيها، ومن شَرِّ فِتَنِ الليلِ والنَّهارِ، ومِنْ كُلِّ طارقٍ، إلا طارقًا يَطْرُقُ بخيرٍ، يا رحمن' WHERE id = 213;
-- p138
UPDATE contents SET body = 'لا إلهَ إلَّا اللهُ الواحِدُ القهَّارُ، ربُّ السماواتِ والأرضِ وما بينهما العزيزُ الغَفَّارُ' WHERE id = 215;
UPDATE contents SET body = 'باسْمِكَ اللهمَّ وضعتُ جَنْبِي، وَبِكَ أرْفَعُهُ، إنْ أمْسَكْتَ نفسي فارْحمْها، وإنْ رَدَدتَّها فاحفظْها بما تحفظُ به عِبادَكَ الصالحين' WHERE id = 974;
-- p139
UPDATE contents SET body = 'وقال ﷺ: «أقربُ ما يكونُ الرَّبُّ من العبدِ، في جَوفِ الليلِ الآخِرِ، فإنِ استَطَعتَ أن تكونَ مِمَّن يَذْكُرُ اللهَ في تِلكَ السَّاعةِ؛ فَكُن».' WHERE id = 1652;
UPDATE contents SET body = 'وقال ﷺ: «يَنزِلُ رَبُّنا تَبَارَكَ وَتَعَالَى كُلَّ ليلةٍ إلى سماءِ الدُّنيا، حينَ يبقى ثُلُثُ اللَّيلِ الآخِرِ، فيقولُ: مَن يدعوني فأستجيبَ له؟ مَن يسألُني فَأُعْطِيَه؟ مَن يستغفِرُني فأغفِرَ له؟».' WHERE id = 1653;
-- p140
UPDATE contents SET body = 'إذا هَمَّ بالأمرِ، فَلْيَرْكَعْ ركعتين من غير الفريضة، ينوي بهما الاستخارة، ثُمَّ يقول:' WHERE id = 1260;
-- p142
UPDATE contents SET body = '١- لا إلهَ إلَّا اللهُ العظيمُ الحليمُ، لا إلهَ إلَّا اللهُ رَبُّ العرشِ العظيمِ، لا إلهَ إلَّا اللهُ رَبُّ السماواتِ والأرضِ، لا إلهَ إلَّا اللهُ رَبُّ العرشِ الكريمِ' WHERE id = 218;
UPDATE contents SET body = '٢- لا إلهَ إلَّا اللهُ الحليمُ الكريمُ، لا إلهَ إلَّا اللهُ العليُّ العظيمُ، لا إلهَ إلَّا اللهُ رَبُّ السماواتِ السَّبعِ، وربُّ العرشِ الكريمِ' WHERE id = 219;
UPDATE contents SET body = '٣- لا إلهَ إلَّا أنتَ، سُبْحانَكَ، إنِّي كُنتُ من الظالمين' WHERE id = 220;
UPDATE contents SET body = '٤- يا حَيُّ يا قَيُّومُ، بِرَحمتِكَ أستغيثُ' WHERE id = 221;
UPDATE contents SET body = '٦- اللهُ اللهُ رَبِّي، لا أُشْرِكُ بِهِ شيئًا' WHERE id = 223;
UPDATE contents SET body = '٧- اللهمَّ رحمتَكَ أرجو، فلا تَكِلْني إلى نَفْسِي طَرْفَةَ عَيْنٍ، وَأَصْلِحْ لي شأني كُلَّهُ، لا إلهَ إلَّا أنتَ' WHERE id = 224;
UPDATE contents SET body = '٥- وَلْيَكُنْ أكثر دعائه أن يقول:' WHERE id = 1262;
-- p143
UPDATE contents SET body = '٨- اللهمَّ إنِّي أعوذُ بكَ مِنْ جَهْدِ البلاء، ودَرَكِ الشقاء، وسُوءِ القضاء، وشماتةِ الأعداء' WHERE id = 225;
-- p144
UPDATE contents SET body = '٩- اللهمَّ إني عبدُكَ، وابنُ عبدِكَ، وابنُ أَمَتِكَ، في قبضتِكَ، ناصيتي بيدِكَ، ماضٍ فِيَّ حُكْمُكَ، عَدْلٌ فِيَّ قضاؤُكَ، أسألُكَ بِكُلِّ اسمٍ هُوَ لَكَ، سَمَّيْتَ بهِ نَفْسَكَ، أو أَنْزَلْتَه في كِتابِكَ، أو عَلَّمْتَهُ أحدًا مِنْ خَلْقِكَ، أو اسْتأثَرتَ بهِ فِي عِلْمِ الغيبِ عِنْدَكَ، أن تَجْعَلَ القرآنَ العظيمَ رَبيعَ قَلْبِي، ونورَ صَدْرِي، وجِلاءَ حُزْنِي، وذَهابَ هَمِّي' WHERE id = 226;
-- p145
UPDATE contents SET body = '٢- اللهمَّ أنتَ عَضُدِي، وأنتَ نصيري، بِكَ أَحُولُ، وبِكَ أَصُولُ، وبِكَ أُقاتِلُ' WHERE id = 228;
UPDATE contents SET body = '٣- اللهُ اللهُ رَبِّي، لا شريكَ له' WHERE id = 229;
UPDATE contents SET body = '٤- اللهمَّ إنَّا نجعَلُكَ في نُحورِهِم، ونعوذُ بِكَ مِنْ شُرورِهم' WHERE id = 230;
UPDATE contents SET body = '٥- اللهمَّ اكْفِنِيهِمْ بما شِئْتَ' WHERE id = 231;
UPDATE contents SET body = '٦- حَسْبُنا اللهُ ونِعْمَ الوكيلُ' WHERE id = 232;
UPDATE contents SET body = '٧- لا حَوْلَ ولا قُوَّةَ إلَّا باللهِ' WHERE id = 233;
UPDATE contents SET body = '٨- اللهمَّ استُرْ عَوْراتِنا، وآمِنْ رَوْعاتِنا' WHERE id = 234;
-- p146
UPDATE contents SET body = '٩- اللهُمَّ مُنْزِلَ الكتابِ، ومُجريَ السَّحابِ، سَريعَ الحسابِ، اهزِمِ الأحزابَ، اللهُمَّ اهزِمْهُمْ، وزَلزِلْهُم، وانْصُرْنا عليهم' WHERE id = 235;
UPDATE contents SET body = '٢- أعوذُ باللهِ السَّمِيعِ العليمِ من الشَّيْطانِ الرَّجِيمِ؛ مِنْ هَمْزِهِ ونَفْخِهِ ونَفْثِهِ' WHERE id = 237;
UPDATE contents SET body = '٤- أَلْعَنُكَ بلعنةِ اللهِ التَّامَّةِ [ثلاث مرَّاتٍ]' WHERE id = 239;
UPDATE contents SET body = '٥- ويُؤَذِّنُ أذانَ الصلاةِ' WHERE id = 240;
-- p147
UPDATE contents SET body = '٦- أعوذُ بكلماتِ اللهِ التَّامَّاتِ التي لا يُجاوِزُهُنَّ بَرٌّ ولا فَاجِرٌ، مِنْ شَرِّ ما خَلَقَ وذَرَأَ وبَرَأَ، ومِنْ شَرِّ ما ينزِلُ من السماءِ، ومن شَرِّ ما يَعْرُجُ فيها، ومن شرِّ ما ذَرَأَ في الأرضِ، وبَرَأَ، ومن شَرِّ ما يخرُجُ منها، ومن شَرِّ فِتَنِ الليلِ والنهارِ، ومن شَرِّ كُلِّ طارقٍ يطرقُ، إلَّا طارقًا يَطرُقُ بخيرٍ يا رحمن' WHERE id = 241;
-- p148
UPDATE contents SET body = 'اللهُمَّ لا سَهْلَ إلَّا ما جَعَلْتَهُ سهلًا، وأنتَ تَجْعَلُ الحَزْنَ إذا شِئتَ سَهْلًا' WHERE id = 243;
UPDATE contents SET body = 'اللهمَّ لا خيرَ إلَّا خيرُكَ، ولا طَيْرَ إلَّا طَيْرُكَ، ولا إلهَ غيرُكَ' WHERE id = 244;
UPDATE contents SET body = 'يَمْضِي فيها مُتَوَكِّلًا على اللهِ تعالى، ويُكَفِّرُ عن وِزْرِ تطيُّره بأَنْ يقول:' WHERE id = 1264;
-- p149
UPDATE contents SET body = 'إنَّا للهِ وإنّا إليهِ راجعونَ، اللهمَّ أْجُرْنِي في مُصِيبَتي، وأَخْلِفْ لي خيرًا منها' WHERE id = 245;
UPDATE contents SET body = 'اللهُمَّ اكْفِنِي بِحلالِكَ عَنْ حَرَامِكَ، وَأَغْنِنِي بِفَضْلِكَ عَمَّنْ سِواكَ' WHERE id = 246;
-- p150
UPDATE contents SET body = 'أُعِيذُكُم بكلماتِ اللهِ التَّامَّةِ، مِنْ كُلِّ شيطانٍ وهامَّةٍ، ومن كُلِّ عينٍ لامَّةٍ' WHERE id = 248;
-- p156
UPDATE contents SET body = '١- آمنْتُ باللهِ وَرُسُلِه' WHERE id = 249;
UPDATE contents SET body = '٢- هُوَ الأوَّلُ والآخِرُ، والظَّاهِرُ والباطِنُ، وهُوَ بِكُلِّ شيءٍ عليم' WHERE id = 250;
UPDATE contents SET body = '٣- اللهُ أَحَدٌ، اللهُ الصَّمَدُ، لَمْ يَلِدْ، ولَمْ يُولَدْ، ولَمْ يَكُنْ له كُفُوًا أَحَدٌ' WHERE id = 251;
UPDATE contents SET body = '٤- أعوذُ باللهِ السميعِ العليمِ من الشيطانِ الرجيمِ، وَمِنْ فِتْنَتِهِ' WHERE id = 252;
-- p158
UPDATE contents SET body = 'أعوذُ بِعزَّةِ اللهِ وقُدْرَتِهِ مِنْ شَرِّ ما أَجِدُ وأُحاذِرُ [سبع مرات]' WHERE id = 256;
-- p159
UPDATE contents SET body = '٦- اللهُ رَبِّي، لا شريكَ له' WHERE id = 258;
UPDATE contents SET body = '٨- اللهم آتِنا في الدنيا حَسَنَةً، وفي الآخِرَةِ حَسَنَةً، وَقِنا عذابَ النار' WHERE id = 260;
UPDATE contents SET body = 'اللهمَّ ارْزُقْني شهادةً في سبيلِكَ، واجعلْ مَوْتِي في بلدِ رسولِكَ صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمَ' WHERE id = 976;
-- p160
UPDATE contents SET body = '٢- اكشِفِ الباسَ، رَبَّ النَّاسِ، إلهَ الناسِ' WHERE id = 262;
UPDATE contents SET body = '٣- اللهمَّ اشْفِ عَبْدَكَ، يَنْكَأْ لكَ عَدُوًّا، أو يَمْشِ لكَ إلى الصلاةِ' WHERE id = 263;
UPDATE contents SET body = '٤- اكشِفِ الباسَ، رَبَّ الناسِ، لا يَكْشِفُ الكَرْبَ غيرُكَ' WHERE id = 264;
-- p161
UPDATE contents SET body = '٦- امسَحِ الباسَ، رَبَّ الناسِ، بيدِكَ الشِّفاءُ، لا كاشِفَ له إلَّا أنتَ' WHERE id = 266;
UPDATE contents SET body = '١- باسمِ اللهِ، تُرْبَةُ أرضِنا، بِرِيقَةِ بَعْضِنَا، يُشفى بِهِ سَقِيمُنا، بإذنِ رَبِّنا' WHERE id = 267;
UPDATE contents SET body = '٧- أسْألُ اللهَ العظيمَ، رَبَّ العرشِ العظيمِ أن يَشْفِيَكَ [سبع مرات]' WHERE id = 977;
-- p162
UPDATE contents SET body = '٣- اللهمَّ ربَّ الناسِ، أذهِبِ الباسَ، اشْفِ أنتَ الشَّافي، لا شفاءَ إلَّا شفاؤُكَ، شفاءً لا يُغادِرُ سَقَمًا' WHERE id = 269;
UPDATE contents SET body = '٤- باسمِ اللهِ أُرقيكَ، مِنْ كُلِّ شيءٍ يُؤذِيكَ، مِنْ شَرِّ كُلِّ نَفْسٍ أو عَينِ حاسدٍ، اللهُ يَشْفِيكَ، باسمِ اللهِ أُرقيكَ' WHERE id = 270;
UPDATE contents SET body = '٥- باسمِ اللهِ يُبْرِيكَ، ومِنْ كُلِّ داءٍ يَشْفِيكَ، وَمِنْ شَرِّ حاسدٍ إذا حَسَدَ، وَشَرِّ كُلِّ ذِي عَيْنٍ' WHERE id = 978;
-- p163
UPDATE contents SET body = '١- إنَّهُ قد حَضَرَ مِنِّي ما ليسَ اللهُ بتاركٍ مِنْهُ أحدًا لِمُوافاةِ يَوْمِ القيامةِ' WHERE id = 271;
UPDATE contents SET body = '٢- ما أرى الأجَلَ إلا اقتربَ، فاتَّقوا اللهَ واصْبِرُوا' WHERE id = 272;
UPDATE contents SET body = 'وعلى المحتَضَرِ أن ينهى عَمَّا يتوقَّعُ حدوثَه من منكرٍ أو بدعةٍ، إذا آنس من ذويه ذلك.' WHERE id = 1618;
-- p164
UPDATE contents SET body = 'لا إلهَ إلا اللهُ، واللهُ أكبرُ، لا إلهَ إلا اللهُ وحدَهُ، لا إلهَ إلا اللهُ، لا شريكَ له، لا إلهَ إلا اللهُ، له الملكُ، وله الحمدُ، لا إلهَ إلا اللهُ، ولا حولَ ولا قوَّةَ إلا باللهِ' WHERE id = 274;
-- p165
UPDATE contents SET body = '١- لا إلهَ إلا اللهُ، إنَّ للموتِ سَكَراتٍ، اللهمَّ اغفِرْ لي، وارحَمْني، وأَلْحِقْني بالرَّفِيقِ الأعلى' WHERE id = 275;
-- p166
UPDATE contents SET body = 'لا إلهَ إلَّا اللهُ، محمدٌ رسولُ اللهِ' WHERE id = 979;
UPDATE contents SET body = 'اللهمَّ اغفِرْ لفلانٍ -ويُسَمِّي الميتَ-، وارفعْ درجتَهُ في المهديِّينَ، واخْلُفْهُ في عَقِبِهِ في الغابرينَ، واغفِرْ لنا وله يا رَبَّ العالمينَ، وافْسَحْ له في قَبْرِهِ، ونَوِّرْ له فيهِ' WHERE id = 980;
UPDATE contents SET body = 'اللهمَّ اغفرْ لي وله، وأَعْقِبْني منه عُقْبى حسنةً' WHERE id = 981;
-- p167
UPDATE contents SET body = '١- إنَّا للهِ، وإنّا إليهِ راجعونَ، اللهمَّ أْجُرْنِي في مُصيبتي، وأَخْلِفْ لي خيرًا منها' WHERE id = 982;
UPDATE contents SET body = '٢- إنَّ العينَ تدْمَعُ، والقَلبَ يحزنُ، ولا نَقُولُ إلَّا ما يُرْضِي رَبَّنا، وإنَّا بِفِراقِكَ يا «فلان» لَمحزونون' WHERE id = 983;
UPDATE contents SET body = 'إنَّ للهِ ما أخذَ، وللهِ ما أَعْطى، وكُلُّ شيءٍ عِنْدَهُ إلى أَجَلٍ مُسَمًّى، فَلْتَصْبِرْ، ولتَحْتَسِبْ' WHERE id = 984;
-- p168
UPDATE contents SET body = '١- اللهمَّ اغفِرْ لهُ، وارحَمْهُ، وعافِهِ، واعفُ عنهُ، وأكرِمْ نُزُلَهُ، ووَسِّعْ مُدْخَلَهُ، واغْسِلْهُ بالماءِ والثَّلْجِ والبَرَدِ، ونَقِّهِ مِنَ الخطايا كما يُنَقَّى الثوبُ الأبيضُ من الدَّنَسِ، وأَبدِلْهُ دارًا خَيْرًا مِنْ دارِهِ، وَأَهْلًا خَيْرًا مِنْ أهلِهِ، وَزَوْجًا خَيْرًا مِنْ زوْجِهِ وَأَدْخِلْهُ الجَنَّةَ، وأَعِذْهُ مِن عذابِ القَبْرِ، وَمِنْ عذابِ النارِ' WHERE id = 278;
-- p169
UPDATE contents SET body = '٢- اللهمَّ اغفِرْ لِحَيِّنا ومَيِّتِنا، وشاهِدِنا وغائِبِنا، وصغيرِنا وكبيرِنا، وذَكَرِنا وأُنثانا، اللهمَّ مَن أحييتَهُ مِنَّا فأَحْيِهِ على الإسلامِ، ومَن تَوَفَّيْتَهُ مِنَّا فَتَوَفَّهُ على الإيمانِ، اللهمَّ لا تَحْرِمْنا أجرَهُ، ولا تُضِلَّنا بعدَهُ' WHERE id = 279;
UPDATE contents SET body = '٣- اللهُمَّ أَنْتَ رَبُّها، وَأَنْتَ خَلَقْتَها، وَأَنْتَ هَدَيْتَها لِلْإِسْلامِ، وَأَنْتَ قَبَضْتَ رُوحَها، وَأَنْتَ أَعْلَمُ بِسِرِّها وَعَلانِيَتِها، جِئْنا شُفَعاءَ، فَاغْفِرْ لَها' WHERE id = 280;
UPDATE contents SET body = '٤- اللهمَّ إنَّ فلانَ بنَ فلانٍ في ذِمَّتِكَ وحَبْلِ جِوارِكَ، فَقِهِ فِتنةَ القبرِ وعذابَ النارِ، وأنتَ أهلُ الوَفاءِ والحَقِّ، فاغفرْ له، وارحمْهُ، إنَّكَ أنتَ الغفورُ الرحيمُ' WHERE id = 281;
UPDATE contents SET body = '٥- اللهمَّ عبدُكَ وابنُ أَمَتِكَ، احتاجَ إلى رَحْمَتِكَ، وأَنْتَ غنيٌّ عنْ عذابِهِ، إنْ كانَ مُحْسِنًا؛ فَزِدْ في حسناتِهِ، وإنْ كانَ مُسِيئًا؛ فتَجاوَزْ عَنْهُ' WHERE id = 282;
-- p170
UPDATE contents SET body = 'اللهمَّ إنَّهُ عبدُكَ، وابنُ عبدِكَ، وابنُ أَمَتِكَ، كان يَشْهَدُ أنْ لا إلهَ إلا أنتَ، وأنَّ محمدًا عبدُكَ ورَسُوْلُكَ، وأنتَ أَعْلَمُ بِهِ، اللَّهُمَّ إن كانَ مُحْسِنًا؛ فَزِدْ في حسناتِهِ، وإن كانَ مُسيئًا؛ فتجاوزْ عن سيئاتِهِ، اللهُمَّ لا تَحرِمْنا أجرَهُ، ولا تَفْتِنَّا بعدَهُ' WHERE id = 283;
UPDATE contents SET body = '٢- اللهُمَّ أَعِذْهُ مِنْ عذابِ القبرِ' WHERE id = 986;
UPDATE contents SET body = 'والسُّقْطُ يُصَلَّى عليه، ويُدْعَى لِوالِدِيه بالمغفرةِ والرحمة.' WHERE id = 1636;
-- p171
UPDATE contents SET body = 'استغْفِروا لأخِيكُمْ، وسَلُوا له التثبِيتَ، فإنَّهُ الآنَ يُسْألُ' WHERE id = 286;
-- p172
UPDATE contents SET body = '١- السلامُ عليكم دارَ قومٍ مؤمنين، وأتاكم ما تُوعَدون، وإنَّا إن شاءَ اللهُ بكم لاحِقونَ، اللهمَّ اغفِرْ لأهلِ «هذه المقابرِ»' WHERE id = 287;
UPDATE contents SET body = '٢- أو: السلامُ عليكم أهلَ دارِ قومٍ مؤمنين، وإنَّا وإيَّاكُم، وما تُوعَدُونَ غدًا مُؤَجَّلون، وإنَّا إن شاءَ اللهُ بكم لاحِقون، اللهمَّ اغفِرْ لأهلِ «هذه المقابرِ»' WHERE id = 288;
UPDATE contents SET body = '٣- أو: السلامُ على أهلِ الدِّيارِ من المؤمنين والمسلمين، وَيَرْحَمُ اللهُ المُستَقدِمينَ منكم ومِنَّا والمُستأخِرين، وإنَّا إن شاءَ اللهُ بِكُم لاحِقون' WHERE id = 289;
-- p173
UPDATE contents SET body = '٤- أو: السلامُ عليكم أهلَ الديارِ منَ المؤمنينَ والمسلمين، وإنَّا إنْ شاءَ اللهُ بكم لَلاحِقُونَ، أنتم لنا فَرَطٌ، ونحن لَكُمْ تَبَعٌ، أسألُ اللهَ لنا ولَكُمُ العافيةَ' WHERE id = 290;
-- p174
UPDATE contents SET body = 'اتَّقي اللهَ، واصْبِري' WHERE id = 987;
-- p175
UPDATE contents SET body = 'اللهُ أكبرُ، اللهمَّ أَهِلَّهُ علينا بالأمنِ والإيمانِ، والسلامَةِ والإسلامِ، والتوفيقِ لِمَا تُحِبُّ وتَرضَى، رَبُّنا وَرَبُّكَ الله' WHERE id = 293;
-- p176
UPDATE contents SET body = 'اللهمَّ إنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ، فاعْفُ عَنِّي' WHERE id = 988;
UPDATE contents SET body = 'وإذا صامَ؛ فلا يَرْفُثْ، ولا يَجْهَلْ، وإنِ امْرُؤٌ قاتَلَهُ أو شاتَمَهُ، فَلْيَقُلْ:' WHERE id = 1314;
-- p177
UPDATE contents SET body = 'أستودِعُكُمُ اللهَ الذي لا تَضِيعُ ودائِعُهُ' WHERE id = 298;
UPDATE contents SET body = 'اعلم أنَّ الأذكار التي تُستَحَبُّ للحاضِرِ في الليلِ والنَّهارِ، واختلافِ الأحوال، وغير ذلك؛ تُستحبُّ للمسافِرِ أيضًا، ويَزيد المسافرُ أذكارًا نوردها فيما يلي إن شاء الله.' WHERE id = 1056;
-- p179
UPDATE contents SET body = '١- الحمدُ للهِ
﴿ سُبۡحَٰنَ ٱلَّذِي سَخَّرَ لَنَا هَٰذَا وَمَا كُنَّا لَهُۥ مُقۡرِنِينَ ١٣ وَإِنَّآ إِلَىٰ رَبِّنَا لَمُنقَلِبُونَ ﴾
الحمدُ للهِ، الحمدُ للهِ، الحمدُ للهِ، اللهُ أكبرُ، اللهُ أكبرُ، اللهُ أكبرُ، سبحانَكَ إنِّي ظلمتُ نفسي، فاغفِرْ لي، إنه لا يغفِرُ الذنوبَ إلَّا أنتَ' WHERE id = 306;
-- p180
UPDATE contents SET body = '٢- اللهم إنَّا نسألُكَ في سَفَرِنَا هذا البِرَّ والتقوى، ومن العملِ ما تَرْضَى، اللهم هَوِّنْ علينا سَفَرَنَا هذا، واطْوِ عَنَّا بُعْدَه، اللهُمَّ أنتَ الصَّاحِبُ في السَّفَرِ، والخَلِيفَةُ في الأهل' WHERE id = 307;
UPDATE contents SET body = '٤- اللهم إني أعوذُ بِكَ مِنْ وَعْثاءِ السفرِ، وكَآبَةِ المنظرِ، وسُوءِ المُنقَلَبِ في المالِ والأهل' WHERE id = 308;
-- p181
UPDATE contents SET body = '٥- اللهم إنِّي أعوذُ بِكَ من الحَوْرِ بعدَ الكَوْنِ، ومن دعوةِ المظلوم، ومن سُوءِ المنظرِ في الأهلِ والمالِ' WHERE id = 309;
-- p182
UPDATE contents SET body = 'سَمَّعَ سامِعٌ بِحَمْدِ اللهِ وحُسْنِ بَلائِه علينا، ربَّنا صاحِبْنا، وأفْضِلْ علينا، عائذًا باللهِ من النار' WHERE id = 314;
-- p183
UPDATE contents SET body = '٢- سبحانَ الذي سَخَّرَ لنا هذا، وما كُنَّا له مُقْرِنين، وإنَّا إلى رَبِّنا لَمُنقَلِبون، اللهمَّ إنَّا نسألُكَ في سفرِنا هذا البِرَّ والتقوى، ومن العَمَلِ ما ترضى، اللهُمَّ هَوِّنْ علينا سَفَرَنا هذا، واطْوِ عنَّا بُعْدَه، اللهم أنتَ الصاحِبُ في السَّفَرِ، والخليفةُ في الأهلِ، اللهم إنِّي أعوذُ بِكَ من وَعْثاءِ السفرِ، وكآبَةِ المنظرِ، وسُوءِ المُنقَلَبِ في المالِ والأهلِ' WHERE id = 872;
-- p185
UPDATE contents SET body = 'فإذا استوى على ما يركبه، وابتدأ السيرَ؛ استقبَلَ القبلةَ، وحَمِدَ اللهَ، وسَبَّحَ، وكَبَّرَ.' WHERE id = 1320;
-- p187
UPDATE contents SET body = 'لبيكَ اللهُمَّ لبيكَ، لَبَّيْكَ لا شريكَ لكَ لَبَّيْكَ، إنَّ الحمدَ والنعمةَ لكَ والمُلْكَ، لا شريكَ لَكَ' WHERE id = 989;
-- p189
UPDATE contents SET body = '١- اللهمَّ صَلِّ على محمدٍ وآلِهِ وسَلِّمْ، اللهمَّ افتحْ لي أبوابَ رحمتِكَ' WHERE id = 322;
-- p190
UPDATE contents SET body = 'اللهم أنتَ السلامُ، ومنكَ السلامُ، فَحَيِّنا رَبَّنا بالسَّلامِ' WHERE id = 324;
UPDATE contents SET body = 'فإذا أتى المعتمِرُ الحجرَ الأسودَ أمسكَ عن التلبيةِ قبل أن يشرعَ في الطواف.' WHERE id = 1337;
-- p192
UPDATE contents SET body = 'وينبغي له أن يكون في طوافِه خاشعًا مُتَخَشِّعًا، حاضرَ القلب، ملازمَ الأدبِ بظاهره وباطنه، وفي هيئته وحركته، ونظره، فإنَّ الطوافَ صلاةٌ، فيتأدَّبُ بآدابها، ويستشعر بقلبه عظمةَ مَن يطوف ببيته، ويخفض صوته، ويُقِلُّ الكلام، فإنْ نَطَقَ فلا ينطقُ إلَّا بخيرٍ، ويصونُ نظرَه عمَّن لا يحل النظر إليه.' WHERE id = 1342;
-- p193
UPDATE contents SET body = 'وإذا انتهى من الشوط السابع أزالَ الاضطباعَ، فَغَطَّى كَتِفَهُ الأيمنَ، وانْطَلَقَ إلى مَقامِ إبراهيمَ عليه السلام، وقَرَأَ بصوتٍ مسموعٍ:' WHERE id = 1345;
-- p194
UPDATE contents SET body = 'أبدأُ بما بَدَأَ اللهُ بِهِ' WHERE id = 995;
UPDATE contents SET body = 'اللهُ أكبرُ، اللهُ أكبرُ، لا إله إلَّا اللهُ وحدَه، لا شريكَ له، له الملكُ، وله الحمدُ، يُحيي ويُميتُ، وهو على كُلِّ شيءٍ قديرٌ، لا إله إلا اللهُ وحدَه، لا شريكَ له، أنجَزَ وَعْدَه، ونَصَرَ عبدَه، وهَزَمَ الأحزابَ وحدَه' WHERE id = 996;
-- p195
UPDATE contents SET body = 'لثبوته عن ابن مسعودٍ وابن عمر رضي الله عنهم.' WHERE id = 1357;
UPDATE contents SET body = 'ويُسْتَحَبُّ أن يدعوَ بين الصفا والمروة في مشيه وسعيه، ويُسْتَحَبُّ قراءةُ القرآن فيه.' WHERE id = 1358;
-- p196
UPDATE contents SET body = 'وإذا انطلق إلى عَرَفاتٍ يومَ التاسِعِ أَكْثَرَ من التلبيةِ، وقَرَنَها بالتكبيرِ.' WHERE id = 1361;
-- p197
UPDATE contents SET body = 'قال شيخ الإسلام ابنُ تَيْمِيَّةَ رحمه الله: «ولم يُعَيِّنِ النَّبِيُّ ﷺ لِعَرَفَةَ دُعاءً، ولا ذِكْرًا، بل يدعو الرجلُ بما شاء من الأدعيةِ الشرعية، وكذلك يُكَبِّرُ، ويُهَلِّلُ، ويذكر الله تعالى، حتى تغربَ الشمسُ».اهـ.' WHERE id = 1365;
-- p198
UPDATE contents SET body = 'لَا إِلَهَ إِلَّا اللهُ وَحدَهُ، لَا شَرِيكَ لَهُ، لَهُ المُلْكُ، وَلَهُ الحَمدُ، وهُوَ علَى كُلِّ شيءٍ قديرٌ' WHERE id = 334;
UPDATE contents SET body = 'قال رسول الله ﷺ: «أَفضلُ الدُّعَاءِ دُعَاءُ يَومِ عَرَفَةَ، وَأَفضَلُ مَا قُلْتُهُ أَنَا والنَّبِيُّونَ مِن قَبلِي:' WHERE id = 1366;
UPDATE contents SET body = 'وَلْيُكْثِرْ من التسبيحِ والتهليلِ والتكبيرِ والتلبيةِ، ونحوها من الأذكارِ والأدعيةِ.' WHERE id = 1367;
-- p201
UPDATE contents SET body = 'وإذا أتى مِنًى، وطلعتِ الشمسُ، لا يُعَرِّجُ على غير الرمي، فيبدأ برمي جمرة العقبة، فيقف تحتها، ويجعل مكَّةَ عن يساره، ومِنًى عن يمينه، ويستقبل العقبة، ثم يرمي بيده اليمنى، ويكبِّر مع كل حصاة.' WHERE id = 1374;
-- p202
UPDATE contents SET body = 'وبعد رَمْيِ الجمرة الثانية، يأخذ ذاتَ الشمال، فيقوم طويلًا مُستقبِلَ القبلةِ، ويدعو رافعًا يديه.' WHERE id = 1378;
UPDATE contents SET body = 'وليس بعد رمي جمرة العقبة (الكبرى) قيامٌ ولا وقوفٌ، غيرَ أنه يَجْعَلُ البيتَ عن يسارِه، ومِنًى عن يمينه، ويرمي.' WHERE id = 1379;
-- p203
UPDATE contents SET body = 'ويُكثر ذِكْرَ الله عَزَّ وَجَلَّ في أيَّامِ التشريق، قال رسول الله ﷺ: «أَيَّامُ التَّشرِيقِ أَيَّامُ أَكلٍ، وَشُرْبٍ، وَذِكْرٍ للهِ»، ويلزم الاستغفارَ والتكبيرَ ودعاءَ:' WHERE id = 1382;
-- p204
UPDATE contents SET body = '٢- باسمِ اللهِ، اللهمَّ صَلِّ على محمدٍ، وأزواجِ محمدٍ' WHERE id = 339;
UPDATE contents SET body = 'أو: اللهمَّ صَلِّ على محمدٍ وآلِهِ وسَلِّمْ' WHERE id = 340;
UPDATE contents SET body = 'فإذا فرغ من المناسك، وأراد الخروجَ من مكَّةَ، طافَ للوداع، بلا اضطباع ولا رَمَل، ثُمَّ صلَّى ركعتي الطواف، فيكون آخر عهده بالبيت.' WHERE id = 1383;
-- p205
UPDATE contents SET body = '٣- اللهمَّ افتَحْ لي أبوابَ رحمتِكَ' WHERE id = 1001;
UPDATE contents SET body = 'فإذا أراد أن يدعوَ؛ تَحَوَّلَ عن القبر، واستقبَل القبلة.' WHERE id = 1388;
-- p206
UPDATE contents SET body = '٣- أو: السَّلامُ على أهلِ الديارِ من المؤمنين والمسلمين، ويَرْحَمُ اللهُ المستقدمينَ منكم ومِنَّا والمُستأخِرين، وإنَّا إنْ شاء اللهُ بِكُمْ لاحِقونَ' WHERE id = 350;
-- p207
UPDATE contents SET body = '٤- أو: السلامُ عليكم أهلَ الدِّيارِ من المؤمنين والمسلمين، وإنَّا إن شاء اللهُ بكم لَلَاحِقون، أنتم لنا فَرَطٌ، ونحن لكم تَبَعٌ، أسْألُ اللهَ لنا ولكم العافيةَ' WHERE id = 351;
-- p208
UPDATE contents SET body = 'يوصيه بتقوى الله تعالى، ومَنْ مَعَهُ مِنَ المسلمين خيرًا، ثم يقول:' WHERE id = 1290;
-- p214
UPDATE contents SET body = 'اللهم بارِكْ لنا فيه، وزِدْنا منه' WHERE id = 371;
-- p215
UPDATE contents SET body = '٣- الحمد لله الذي أطعَمَ وسَقَى، وسَوَّغَهُ، وجعلَ له مَخْرَجًا' WHERE id = 374;
-- p216
UPDATE contents SET body = '١- اللهم بارِكْ لهم فيما رَزَقْتَهم، واغفِرْ لهم وَارْحَمْهُم' WHERE id = 378;
UPDATE contents SET body = 'اللهم أطعِمْ مَنْ أطعمَني، واسقِ مَنْ سَقاني' WHERE id = 380;
UPDATE contents SET body = 'اللهم إنِّي أسألُكَ مِنْ فَضْلِكَ ورحمتِكَ، فإنه لا يملِكُها إلا أنت' WHERE id = 877;
-- p217
UPDATE contents SET body = 'أو: الحمدُ للهِ على كُلِّ حالٍ' WHERE id = 382;
UPDATE contents SET body = 'أو: الحمدُ للهِ' WHERE id = 384;
UPDATE contents SET body = 'يَرْحَمُكَ اللهُ' WHERE id = 385;
-- p218
UPDATE contents SET body = 'يهديكم اللهُ، ويُصْلِحُ بالَكُم' WHERE id = 386;
-- p219
UPDATE contents SET body = 'إنَّ الحمدَ للهِ، نحمَدُه، ونستعينُه، ونستغفِرُه، ونعوذُ باللهِ من شُرورِ أنفسِنا، ومن سيئاتِ أعمالِنا، من يهدِه اللهُ فلا مُضِلَّ له، ومن يُضْلِلْ فلا هادِيَ له، وأشهدُ أنْ لا إله إلَّا اللهُ وحدَه، لا شريكَ له، وأشهدُ أنَّ محمدًا عبدُه ورسولُه' WHERE id = 388;
-- p221
UPDATE contents SET body = '٢- أو: بَارَكَ اللهُ لك، وبارَكَ عليك، وجَمَعَ بينكما في خيرٍ' WHERE id = 394;
UPDATE contents SET body = '٣- أو: اللهُمَّ بارِكْ فيهما، وبَارِكْ لهما في بنائهما' WHERE id = 395;
