UPDATE contents SET body = 'اللهم إنِّي أسألُكَ من خيرِها، وخيرِ ما جَبَلْتَها عليه، وأعوذُ بك من شَرِّها، وشَرِّ ما جَبَلْتَها عليه' WHERE id = 397;
-- p225
UPDATE contents SET body = 'سبحانَ الذي يُسَبِّحُ الرعدُ بحمدِه، والملائكةُ مِن خِيفَتِهِ' WHERE id = 407;
UPDATE contents SET body = 'سُبحانَ مَنْ سَبَّحْتَ له' WHERE id = 408;
UPDATE contents SET body = 'وكان عبدُ الله بن الزبير رضي الله عنهما إذا سَمِعَ الرَّعدَ، تركَ الحديثَ، وقال:' WHERE id = 1271;
-- p226
UPDATE contents SET body = 'مُطِرْنا بفَضْلِ اللهِ ورحمتِهِ' WHERE id = 409;
UPDATE contents SET body = 'اللَّهُمَّ حَوالَيْنا، ولا علينا، اللَّهُمَّ على الآكامِ والظِّرابِ، وبُطونِ الأوديةِ، ومنابتِ الشَّجَرِ' WHERE id = 410;
-- p229
UPDATE contents SET body = 'وإذا حدثت له نِعمةٌ أو كرامةٌ، قال:' WHERE id = 1580;
-- p233
UPDATE contents SET body = 'أَحَبَّكَ الذي أحبَبتَني لهُ' WHERE id = 433;
UPDATE contents SET body = 'بارَكَ اللهُ لَكَ في أهْلِكَ ومالِكَ' WHERE id = 436;
-- p234
UPDATE contents SET body = 'أمسِكْ، لا تُسْمِعْهُ فَتُهْلِكَهُ' WHERE id = 439;
UPDATE contents SET body = 'أو: وَيْحَكَ! قَطَعْتَ عُنُقَ صاحِبِكَ' WHERE id = 440;
UPDATE contents SET body = 'أَحْسَبُهُ كذا، واللهُ حَسِيبُهُ، ولا أُزَكِّي على اللهِ أحدًا' WHERE id = 441;
-- p235
UPDATE contents SET body = 'أخذْنا فألَكَ مِنْ فِيكَ' WHERE id = 444;
UPDATE contents SET body = 'لا، ومُقَلِّبِ القُلوبِ' WHERE id = 449;
-- p236
UPDATE contents SET body = 'الحمدُ للهِ الذي بِنِعْمَتِهِ تَتِمُّ الصالِحاتُ' WHERE id = 452;
UPDATE contents SET body = 'الحمدُ للهِ على كُلِّ حالٍ' WHERE id = 453;
-- p237
UPDATE contents SET body = '٥- اللَّهُمَّ سَلِّمْني، وسَلِّمْ مِنِّي' WHERE id = 458;
UPDATE contents SET body = '٦- اللَّهُمَّ إنَّا نعوذُ بِكَ أنْ نَرجِعَ على أعقابِنا، أو نُفْتَنَ' WHERE id = 459;
UPDATE contents SET body = '٢- اللَّهُمَّ فَقِّهْهُ في الدِّينِ' WHERE id = 461;
-- p238
UPDATE contents SET body = '٣- اللَّهُمَّ أكْثِرْ مالَهُ ووَلَدَهُ، وبارِكْ لهُ فيما أعْطيتَهُ' WHERE id = 462;
UPDATE contents SET body = 'أو: الحمدُ للهِ الذي عافاني ممَّا ابتلاكَ بهِ، وفَضَّلَنِي عليكَ، وعلى كثيرٍ من عبادِهِ تَفْضِيلًا' WHERE id = 1562;
-- p239
UPDATE contents SET body = 'اللَّهُمَّ إنِّي أسألُكَ من خيرِها، وخيرِ ما جَبَلْتَها عليهِ، وأعوذُ بِكَ من شَرِّها، وشرِّ ما جَبَلْتَها عليهِ' WHERE id = 466;
-- p240
UPDATE contents SET body = 'اللَّهُمَّ بارِكْ لنا في ثَمَرِنا، وبارِكْ لنا في مَدينَتِنا، وبارِكْ لنا في صاعِنا، وبارِكْ لنا في مُدِّنا، بركةً معَ بركةٍ' WHERE id = 467;
UPDATE contents SET body = '٣- اللَّهُمَّ بارِكْ فيهِ، ولا تَضُرَّهُ' WHERE id = 469;
-- p241
UPDATE contents SET body = '٤- أُعيذُكَ بكلماتِ اللهِ التَّامَّةِ، من كُلِّ شيطانٍ وهامَّةٍ، ومن كُلِّ عينٍ لَّامَّةٍ' WHERE id = 470;
UPDATE contents SET body = 'اللهمَّ إنِّي أسألُكَ مِنْ فَضْلِكَ' WHERE id = 471;
UPDATE contents SET body = 'لَيتَني أُوتيتُ مِثْلَ ما أُوتِيَ فُلانٌ، فَعَمِلْتُ مِثْلَ ما يَعمَلُ' WHERE id = 475;
UPDATE contents SET body = 'اللَّهُمَّ بارِكْ فيهِ' WHERE id = 1570;
-- p242
UPDATE contents SET body = 'اللَّهُمَّ إنِّي أعوذُ بِكَ أنْ أُشْرِكَ بِكَ وأنا أعلمُ، وأستغفِرُكَ لما لا أعلمُ' WHERE id = 474;
-- p243
UPDATE contents SET body = 'رَبِّ اغفِرْ لِي، وتُبْ عَلَيَّ، إنَّكَ أنتَ التَّوَّابُ الغَفورُ' WHERE id = 477;
UPDATE contents SET body = 'فإذا تَفَرَّقوا؛ صَلَّوْا على النبي ﷺ.' WHERE id = 1578;
-- p244
UPDATE contents SET body = 'سُبحانَ اللهِ وبحمدِهِ، سبحانَكَ اللَّهُمَّ وبحمدِكَ، أشهَدُ أنْ لا إلهَ إلَّا أنتَ، أستغفِرُكَ، وأتوبُ إليكَ' WHERE id = 478;
-- p247
UPDATE contents SET body = 'من أنواع الذكر المُطلَق: تلاوة القرآن الكريم، والتهليل، والتكبير، والتسبيح، والتحميد، والحَوْلَقة، والاستغفار، والحسبلة.' WHERE id = 1391;
UPDATE contents SET body = 'ومنها: الصلاة على النبي ﷺ، وبخاصَّة يومُ الجمعة.' WHERE id = 1393;
UPDATE contents SET body = 'ومنها: دعاء الإنسان لوالِدَيْهِ، وأهلِهِ، وذُرِّيَّتِهِ، وأشايخِهِ، وإخوانِهِ في اللهِ، وسائرِ المسلمين.' WHERE id = 1394;
-- p248
UPDATE contents SET body = 'الوِرد:' WHERE id = 1395;
UPDATE contents SET body = 'الوِرد أو الحزب هو مجموعة من الأذكار يلتزمها الذَّاكِرُ، ويواظِب عليها تَقَرُّبًا إلى الله تعالى، وهو تطوع لم يَفْرِضْه الله عليه.' WHERE id = 1396;
UPDATE contents SET body = 'وينصرف الوِرْدُ عند الإطلاقِ إلى تلاوةِ القرآن الكريم، فهو أهمُّ وِرْدٍ يُطالَبُ المسلمُ بالمحافظَةِ عليه يوميًّا؛ كي لا يكونَ ممن اتخذ القرآنَ مهجورًا، وأفضلُ أحوالِ الوِرْدِ القرآني اليومي أن يكونَ في صلاةِ قيامِ الليل.' WHERE id = 1397;
UPDATE contents SET body = 'وقد شاع على ألسِنَةِ السَّلَفِ الصَّالِحِ ومن تَبِعَهم من الخَلَفِ استعمالُ كلمة (الورد) أو (الحزب) منسوبةً إلى الشخص المعين، مقصودًا بها في الأصل وردُ القرآنِ الكريمِ الذي يُتلى في قيامِ الليل.' WHERE id = 1398;
-- p249
UPDATE contents SET body = 'ما هو «الوِرد الشخصي»؟' WHERE id = 1400;
UPDATE contents SET body = 'لقد أمَرَنَا اللهُ تعالى بالإكثارِ من ذكرِ الله: ﴿وَٱذۡكُرُواْ ٱللَّهَ كَثِيرٗا﴾، وقال ﷺ: «استكثروا من الباقيات الصالحات» الحديث، وقال ﷺ: «أكثروا من شهادة أن لا إله إلَّا الله» الحديث، وقال ﷺ: «طُوبَى لِمن وَجَدَ في صحيفتِه استغفارًا كثيرًا»، وقال ﷺ: «أكثِروا من غرس الجنة» الحديث، وقال: «أكثروا من قول: لا حولَ ولا قوَّةَ إلَّا بالله» الحديث.' WHERE id = 1401;
-- p250
UPDATE contents SET body = 'من خصائص (الورد الشخصي) أنه لا يرتبطُ بوقتٍ ولا عددٍ مُحدَّدَيْنِ:' WHERE id = 1403;
UPDATE contents SET body = 'والأصلُ في الورد الشخصي التزامُ المأثورِ عن النبيِّ صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمَ، ويُباحُ غيرُ المأثور بشرط أن لا يجعلَه ديدَنَه وشعارَه كأنَّه سُنَّة، ولا يهجر المأثور انشغالًا به.' WHERE id = 1407;
-- p252
UPDATE contents SET body = 'الحياةُ أوراد' WHERE id = 1409;
UPDATE contents SET body = 'من أرادَ أن يدخلَ الجنَّةَ بغيرِ حسابٍ؛ فَلْيستغرِقْ أوقاتَه في الطَّاعةِ، وذكرِ الله، ومن أرادَ أن تترجَّحَ كِفَّةُ حسناتِه، وتثقلَ موازينُ خيراتِه، فلْيستوعِبْ في الطاعةِ أكثرَ أوقاتِه، ويكفي للتدليل على هذا أنَّ الله سبحانه خاطَبَ أقربَ عبادِه إليه، وأرفعَهم درجةً لديه ﷺ، فقال: ﴿وَٱذۡكُرِ ٱسۡمَ رَبِّكَ بُكۡرَةٗ وَأَصِيلٗا ۝ وَمِنَ ٱلَّيۡلِ فَٱسۡجُدۡ لَهُۥ وَسَبِّحۡهُ لَيۡلٗا طَوِيلًا﴾ [الإنسان: ٢٥، ٢٦]، وقال تعالى: ﴿وَسَبِّحۡ بِحَمۡدِ رَبِّكَ قَبۡلَ طُلُوعِ ٱلشَّمۡسِ وَقَبۡلَ ٱلۡغُرُوبِ ۝ وَمِنَ ٱلَّيۡلِ فَسَبِّحۡهُ وَأَدۡبَٰرَ ٱلسُّجُودِ﴾ [ق: ٣٩، ٤٠]، وقال تعالى: ﴿وَمِنۡ ءَانَآيِٕ ٱلَّيۡلِ فَسَبِّحۡ وَأَطۡرَافَ ٱلنَّهَارِ لَعَلَّكَ تَرۡضَىٰ﴾ [طه: ١٣٠]، وقال عَزَّ وَجَلَّ: ﴿وَأَقِمِ ٱلصَّلَوٰةَ طَرَفَيِ ٱلنَّهَارِ وَزُلَفٗا مِّنَ ٱلَّيۡلِۚ إِنَّ ٱلۡحَسَنَٰتِ يُذۡهِبۡنَ ٱلسَّيِّـَٔاتِ﴾ [هود: ١١٤].' WHERE id = 1410;
-- p254
UPDATE contents SET body = 'عن القاسمِ بن محمدٍ، عن عائشةَ رضي الله عنها، قالت: قال رسولُ الله ﷺ: «أحبُّ الأعمالِ إلى اللهِ أدومُها وإن قَلَّ»، قال: «وكانت عائشةُ إذا عَمِلَتْ العملَ لَزِمَتْه».' WHERE id = 1415;
-- p255
UPDATE contents SET body = 'وسُئلَتْ رضي الله عنها: أيُّ العمل كان أحبَّ إلى رسولِ اللهِ ﷺ؟ فقالت: «الدائم».' WHERE id = 1417;
UPDATE contents SET body = 'وعنها رضي الله عنها، قالت: «كان أحبُّ العملِ إلى رسولِ اللهِ ﷺ الذي يَدُومُ عليه صاحِبُه».' WHERE id = 1418;
UPDATE contents SET body = 'ولذلك تجد عند المداومين على الطاعة إقبالًا وصبرًا عليها، وحُبًّا لها، وتَلَذُّذًا بها؛ كتلاوةِ كلام الله عَزَّ وَجَلَّ، وإدمانِ النَّظَرِ في المصحف الشريف، وكذا نوافل العبادات، فما بالُكَ بحالهم في المحافظة على الفرائض الواجبات؟!' WHERE id = 1420;
-- p256
UPDATE contents SET body = 'وما كان فريضةً على الإنسان فإنَّه فُرِضَ على الدوام، وقد قال تعالى في الحديث القدسي: «وما تقرَّبَ إليَّ عبدي بشيءٍ أحبَّ إليَّ مما افترضتُ عليه»، ثُمَّ قال عَزَّ وَجَلَّ: «ولا يزالُ عبدي يتقرَّبُ إليَّ بالنوافلِ حتَّى أُحِبَّه» الحديث، فقولُه: «ولا يزال» يُعَبِّرُ عن المداومةِ والمواظبةِ على الفرائض والنوافل، وقولُه: «حتى أُحِبَّه» إلخ، يُعَبِّرُ عن ثمرةِ هذه المداومة.' WHERE id = 1422;
-- p257
UPDATE contents SET body = 'فعن أبي موسى رضي الله عنه، قال رسولُ الله ﷺ: «إذا مَرِضَ العبدُ أو سافر؛ كَتَبَ اللهُ له من الأجرِ مثلَ ما كان يعملُ صحيحًا مُقيمًا».' WHERE id = 1425;
-- p258
UPDATE contents SET body = 'ومصداقُ ذلك في قوله تعالى: ﴿لَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ فِيٓ أَحۡسَنِ تَقۡوِيمٖ﴾ أي صورةٍ، ﴿ثُمَّ رَدَدۡنَٰهُ أَسۡفَلَ سَٰفِلِينَ﴾ إلى أرذلِ العمرِ والخَرَف، ﴿إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ﴾ في وقتِ القوةِ والقدرة، فإنَّهم حالَ الكِبَرِ غيرُ منقوصين، وإن عجزوا عن الطاعات، أو أصابهم الخَرَفُ ﴿فَلَهُمۡ أَجۡرٌ غَيۡرُ مَمۡنُونٖ﴾ غيرُ منقطعٍ.' WHERE id = 1428;
-- p259
UPDATE contents SET body = 'بالرغم من أنَّ الناسَ في تعاملهم مع «وسائل التواصل الاجتماعي» ينقسمون إلى ظالمٍ لنفسه، ومُقتصِدٍ، وسابقٍ بالخيراتِ بإذنِ الله، فإننا نُحَذِّرُ هنا من ظلمِ المرءِ نفسَه حين يهدرُ الساعاتِ الطِّوالَ (يتسكَّعُ) في هذه المواقع، وَيُضَيِّعُ حزبَه القرآنيَّ ووِرْدَه الشخصيَّ، ومصالحَه الدنيوية، ويغرق في العالَمِ الافتراضي الذي يطغَى عليه «التقاطُعُ الاجتماعي» بدلًا من «التواصل الحقيقي» الذي عزل الناسَ كلًّا في جزيرته بعيدًا عن التفاعل المباشر بينهم، وجعلهم صَرْعَى للخوض في «ماجَرَيَاتِ» الفَنِّ، والكرة، والسياسة، وجزئياتِ أحوال الناس، ومداخلِهم ومخارجِهم، وتوابعِ ذلك من هَذَيانِ التافهين، وأحوالِ النفوسِ المبطِلةِ الفارغةِ من ذكرِ الله تعالى واليومِ الآخِر.' WHERE id = 1430;
-- p260
UPDATE contents SET body = 'فعلى من عَجَزَ عن كبحِ جِماحِ نفسِه، وفشل في إدارةِ وقتِه بحزمٍ، وأيقن أنَّ «الغولَ العنكبوتيَّ» يلتهمُ عُمُرَه، ويفترسُ رأسَ مالِه، وَيَصُدُّه عن ذكرِ الله وعن الصلاةِ؛ أن يتخلَّى عن جهازِه الذكي «المشؤوم»، ويستبدلَ به جهازًا تقليديًّا بسيطًا لا يتيحُ له الولوجَ إلى عالَمِ «الإنترنت»؛ استدراكًا لما أضاعَ، واغتنامًا لما بَقِيَ من عُمُرِه ﴿مِّن قَبۡلِ أَن يَأۡتِيَ أَحَدَكُمُ ٱلۡمَوۡتُ فَيَقُولَ رَبِّ لَوۡلَآ أَخَّرۡتَنِيٓ إِلَىٰٓ أَجَلٖ قَرِيبٖ فَأَصَّدَّقَ وَأَكُن مِّنَ ٱلصَّٰلِحِينَ ۝ وَلَن يُؤَخِّرَ ٱللَّهُ نَفۡسًا إِذَا جَآءَ أَجَلُهَاۚ وَٱللَّهُ خَبِيرُۢ بِمَا تَعۡمَلُونَ﴾ [المنافقون: ١٠، ١١]، وقال الله تعالى: ﴿ٱقۡتَرَبَ لِلنَّاسِ حِسَابُهُمۡ وَهُمۡ فِي غَفۡلَةٖ مُّعۡرِضُونَ ۝ مَا يَأۡتِيهِم مِّن ذِكۡرٖ مِّن رَّبِّهِم مُّحۡدَثٍ إِلَّا ٱسۡتَمَعُوهُ وَهُمۡ يَلۡعَبُونَ ۝ لَاهِيَةٗ قُلُوبُهُمۡ﴾ الآيات [الأنبياء: ١–٣].' WHERE id = 1431;
-- p265
UPDATE contents SET body = 'إنَّ تلاوة القرآن الكريم آكَدُ الأذكار، وأفضلها على الإطلاق، فلا يوجد ذِكرٌ يوازيه، فضلًا عن أن يكونَ أفضلَ منه، فينبغي المداومة عليها في كل حال: من ليلٍ ونهارٍ، سفرٍ أو حَضَرٍ، فلا يُخَلِّي عنها يومًا وليلة، ولا يفرغ من ختمةٍ حتى يَصِلَها بأخرى.' WHERE id = 1058;
-- p266
UPDATE contents SET body = 'فعن أبي سعيدٍ الخدري رضي الله عنه أنَّ رسولَ الله ﷺ أوصاه، فقال: «... وعليكَ بِذِكرِ اللهِ وتِلاوَةِ القُرآنِ، فإنَّه رُوحُكَ في السماء، وذِكرُكَ في الأرضِ».' WHERE id = 1437;
UPDATE contents SET body = 'وحفلت السُّنَّةُ الشَّرِيفَةُ بالأحاديث التي تُوصِي بقراءة القرآنِ المجيد، وتبين فضائل تلاوته:' WHERE id = 1447;
-- p268
UPDATE contents SET body = 'وعن ابن مسعودٍ رضي الله عنه قال: قال رسول الله ﷺ: «من قَرَأَ حَرفًا من كتابِ الله، فَلَهُ به حسنة، والحسنةُ بعشرِ أمثالِها، لا أقول: ﴿الٓمٓ﴾ حرف، ولكن (ألفٌ) حرف، و(لامٌ) حرف، و(مِيمٌ) حرف».' WHERE id = 1063;
-- p269
UPDATE contents SET body = 'وعن أمير المؤمنين عمر بن الخطاب رضي الله عنه أنَّ النبيَّ ﷺ قال: «إنَّ اللهَ يَرفعُ بهذا الكتابِ أقوامًا، ويَضَعُ آخرينَ».' WHERE id = 1067;
-- p270
UPDATE contents SET body = 'وعن ابن مسعودٍ رضي الله عنه قال: قال رسولُ الله ﷺ: «القرآنُ شافِعٌ مُشَفَّعٌ، وماحِلٌ مُصَدَّقٌ، مَن جعلَهُ أمامَه؛ قادَهُ إلى الجنةِ، ومَن جعلَهُ خلفَهُ؛ ساقَهُ إلى النارِ».' WHERE id = 1068;
UPDATE contents SET body = 'وعن أبي هريرةَ رضي الله عنه قال: قال رسول الله ﷺ: «ما اجتَمَعَ قَومٌ في بَيتٍ مِن بُيوتِ اللهِ تَعالى، يَتلُونَ كِتابَ اللهِ، ويَتَدارَسونَه بَينَهم؛ إلَّا نَزَلتْ عليهمُ السَّكينةُ، وغَشِيَتْهمُ الرَّحمةُ، وحَفَّتْهمُ المَلائِكةُ، وذَكَرَهمُ اللهُ فيمَن عِندَه».' WHERE id = 1069;
UPDATE contents SET body = 'وعن أنسِ بنِ مالكٍ رضي الله عنه قال: قال رسولُ الله ﷺ: «إنَّ لِلهِ أهلينِ من النَّاسِ»، فقيل: مَنْ أهلُ اللهِ منهم؟ قال: «أهلُ القرآنِ، هُم أهلُ اللهِ وخاصَّتُه».' WHERE id = 1070;
-- p271
UPDATE contents SET body = 'وعن ابن عمرو رضي الله عنهما قال: قال رسول الله ﷺ: «يقالُ لصاحِبِ القرآنِ: اقرأْ وارقَ ورتِّلْ، كما كنتَ تُرَتِّلُ في دارِ الدنيا، فإنَّ منزِلَتَكَ عندَ آخِرِ آيةٍ كنتَ تقرؤُها».' WHERE id = 1065;
UPDATE contents SET body = 'وعن أبي سعيدٍ الخدري رضي الله عنه مرفوعًا: «يُقالُ لصاحب القرآنِ إذا دخلَ الجنةَ: اقرأْ واصعد، فيقرأُ، ويَصْعَدُ بكلِّ آيةٍ درجةً، حتى يقرأَ آخِرَ شيءٍ معه».' WHERE id = 1066;
UPDATE contents SET body = 'وعن عثمانَ بنِ عفَّانَ رضي الله عنه قال: قال رسولُ الله ﷺ: «خَيْرُكُم مَنْ تَعَلَّمَ القُرآنَ وعَلَّمَهُ»، وفي روايةٍ: «إنَّ أفضَلَكُم مَن تَعَلَّمَ القرآنَ وعَلَّمَهُ».' WHERE id = 1440;
-- p272
UPDATE contents SET body = 'وعن أبي هريرةَ رضي الله عنه عن النبي ﷺ قال: «يجيءُ القرآنُ -وفي روايةٍ: صاحِبُ القُرآنِ- يومَ القيامةِ، فيقولُ: يا ربِّ حَلِّهِ، فيُلبَسُ تاجَ الكرامَةِ، ثُمَّ يقولُ: يا ربِّ زِدْهُ، فيُلْبَسُ حُلَّةَ الكرامَةِ، ثُمَّ يقولُ: يا ربِّ ارضَ عنْهُ، فيَرْضَى عنه، فَيُقال له: اقرأْ، وارقَ، ويُزادُ بكُلِّ آيةٍ حسنَةً».' WHERE id = 1442;
-- p273
UPDATE contents SET body = 'عن أمير المؤمنين عمر بن الخطاب رضي الله عنه، قال: قال رسول الله ﷺ: «مَن نامَ عن حِزْبِهِ، أوْ عن شَيءٍ منه، فَقَرَأَهُ فيما بيْنَ صَلاةِ الفَجْرِ وصَلاةِ الظُّهْرِ؛ كُتِبَ له كَأنَّما قَرَأَهُ مِنَ اللَّيْلِ».' WHERE id = 1449;
UPDATE contents SET body = 'فالحزبُ هنا حصة معينة من القرآن الكريم يتلوها المرء احتسابًا، ونلاحظ أنَّ رسولَ الله ﷺ في هذا الحديث أضاف الحزبَ إلى الشخصِ: «حزبه»، وأطلق ذلك، ولم يُقَيِّدْهُ بقدرٍ، ويُفْهَمُ من هذا أنَّ تحديدَ مقدارِ (الحزب) أمرٌ شخصي يخضَعُ لظروفِ كُلِّ شخصٍ على حِدَة، وقد اختلفت مسالِكُ الصحابةِ رضي الله عنهم في المقدارِ اليومي الذي يقرؤونه من القرآن الكريم، وتفاوتت أحزابهم في هذا، وإنْ كان قد رُوِيَ عنهم أنهم كانوا يختمونه في سبعة أيَّامٍ.' WHERE id = 1450;
-- p274
UPDATE contents SET body = 'وَلِكُلِّ إنسانٍ أن يختارَ مُدَّةَ خَتْمِ القرآن بما يناسب ظروفه، ولكنَّ الأفضلَ ألَّا يزيد على أربعين يومًا، قال القرطبيُّ رحمه الله: «والأربعون مُدَّةُ الضُّعفاءِ وأُولِي الأشغال»، يلي ذلك الختمُ في ثلاثين يومًا، ثم عشرين، ثم خمسةَ عشرَ يومًا، ثم عشرةِ أيَّام، ثم أسبوع، ثم خمسةِ أيام، ثم ثلاثةِ أيام، وهذا أقصى حالات الاجتهاد الواردة، وفي الحديث: «لا يفقهُ من قرأ القرآنَ في أقلَّ مِنْ ثلاث».' WHERE id = 1451;
-- p276
UPDATE contents SET body = 'عن أمير المؤمنين عثمان بن عفان رضي الله عنه، قال: «لو أن قلوبنا طَهُرَتْ؛ ما شبعت من كلام ربنا، وإنِّي أكرَهُ أنْ يأتِيَ عَلَيَّ يومٌ لا أَنْظُرُ فيه في المصحف».' WHERE id = 1457;
UPDATE contents SET body = 'بل لا يليق بمسلمٍ أن يخلوَ يومُه من (وِرْدٍ) يوميٍّ يتلوه من القرآن الكريم، بل لا بُدَّ أن يكون (وردُكَ) من خصائص هُويتك، وكما تتضمن بطاقةُ هُوِيَّتِكَ بياناتِكَ الشخصيةَ الأساسَ من الاسم والميلاد والوظيفة والعنوان... إلخ؛ كذلك ينبغي أن تتضمن قدرَ (وردِكَ) اليومي من القرآن الكريم، كعلامةٍ مُمَيِّزة مما يخصُّ هُويتك ويُميِّزُها.' WHERE id = 1459;
-- p278
UPDATE contents SET body = 'وَلْيَعرِفْ قَدْرَ نفسه بلا وَكْسٍ ولا شطط، ولا يُجازِفْ في تقديرِ قدراته، فإنَّ «مَنْ كَبَّرَ اللقمةَ غَصَّ فيها» وإنَّ المرْءَ لو تكلَّفَ ما لا يستطيعه فإنه يُضطرُّ إلى الإخلال والانقطاع عما عزم على فعله، وقليلٌ يدوم خيرٌ من كثير ينقطع.' WHERE id = 1466;
UPDATE contents SET body = 'قال ﷺ: «خُذُوا مِنَ الأعمالِ ما تُطِيقونَ؛ فإنَّ اللهَ لا يَمَلُّ حتَّى تَمَلُّوا، وإنَّ أحبَّ الأعمالِ عندَ اللهِ ما دامَ، وإنْ قَلَّ».' WHERE id = 1467;
-- p280
UPDATE contents SET body = 'ومما يعين على المداومة على الوِرْدِ أن يُخَصِّصَ له وقتًا متصلًا في قيامِ الليل، أو في مجلسٍ واحدٍ عَقِيبَ صلاةِ الصبح، وبعد الإتيانِ بأذكارِ الصباحِ، فقد كان عبدُ الرحمنِ ابن أبي ليلى إذا صَلَّى الصبحَ قرأ المصحفَ حتى تطلع الشمس، وكان ثابتٌ البُنانيُّ يفعلُ ذلك أيضًا.' WHERE id = 1472;
UPDATE contents SET body = 'فإنْ لم يناسِبْه ذلك؛ وَزَّعَ وِرْدَه على أوقاتٍ عِدَّةٍ خلالَ اليومِ، أو يربطه بقبل الصلوات أو بعدها، أو كليهما.' WHERE id = 1473;
-- p281
UPDATE contents SET body = '«لا إله إلَّا الله» كلمة أمرها عظيم، وخَطْبُها جسيم، وشأنُها جليل، كلمةٌ على الله كريمة، ولها عنده سبحانه مكانٌ وشأنٌ، أعلاها مُثْمِرٌ، وأسفلُها مُغْدِقٌ، لا توجد في الوجود كلمةٌ أصدقُ ولا أعظمُ ولا أطهر ولا أقدس ولا أشرفُ منها، وليس في الدنيا ولا في الآخِرة كلمةٌ ثبت لها من الفضائل ما ثبت لها، فضائل لا يمكن عَدُّها وحَصْرُها؛ إذ يترتب عليها من الخير العميم، والأجرِ الجزيل، والثوابِ الجليل، ما لا يسنَحُ بخيال، ولا يخطرُ على بال.' WHERE id = 1475;
-- p282
UPDATE contents SET body = '«لا إله إلا الله» تاجُ الموحِّدين، ونور أفئدة المتقين، وحصن الأمان، وسفينة النجاة، وكلمةُ الشهادة، ومِفتاحُ دارِ السعادة.' WHERE id = 1479;
-- p283
UPDATE contents SET body = '«لا إله إلا الله» أصلُ الدين وأساسُه، ورأسُ أمرِه، وساقُ شجرته، وعمودُ فُسطاطِه، وبقيةُ أركان الدين متفرعةٌ عنها، متشعبة منها، مكمِّلاتٌ لها، مقيَّدةٌ بالتزامِ معناها، والعملِ بمقتضاها.' WHERE id = 1481;
UPDATE contents SET body = 'وبها النجاةُ من النار بعد الوُرود، وَبِعَدَمِ التزامِها البقاءُ فيها والخلود، بها تُؤخَذُ الكتبُ باليمين أو الشمال، ويثقل الميزان أو يخِفُّ، وعنها يُسأَلُ الأوَّلون والآخِرون.' WHERE id = 1483;
-- p285
UPDATE contents SET body = '٤- اللهم إني أُشْهِدُكَ، وأُشْهِدُ ملائكتَك، وحَمَلَةَ عرشِكَ، وأُشْهِدُ مَن في السماواتِ ومَن في الأرضِ أنَّك أنتَ اللهُ، لا إله إلا أنتَ وحدَك، لا شريكَ لك، وأشهدُ أنَّ محمدًا عبدُكَ ورسولُك. [ثلاث مرات]' WHERE id = 483;
-- p288
UPDATE contents SET body = 'عن أبي هريرةَ رضي الله عنه أنَّ رسولَ الله ﷺ قال: «ما قَعَدَ قومٌ مقعدًا لم يذكروا فيه الله عَزَّ وَجَلَّ ويُصلُّوا على النبي ﷺ إلَّا كان عليهم حسرَةً يومَ القيامة، وإن دخلوا الجنةَ للثواب».' WHERE id = 1490;
UPDATE contents SET body = 'وعنه رضي الله عنه قال: قال رسول الله ﷺ: «مَن ذُكِرتُ عندَه فَنَسِيَ الصلاةَ عَلَيَّ، خَطِئَ طريقَ الجَنَّةِ».' WHERE id = 1491;
UPDATE contents SET body = 'وعن أميرِ المؤمنينَ عليٍّ رضي الله عنه قال: قال رسول الله ﷺ: «البخيلُ مَنْ ذُكِرْتُ عِنْدَه، ثُمَّ لَمْ يُصَلِّ عَلَيَّ».' WHERE id = 1492;
-- p289
UPDATE contents SET body = 'وعن سعيد بن عميرٍ الأنصاري عن أبيه رضي الله عنه قال: قال رسول الله ﷺ: «من صَلَّى عَلَيَّ مِنْ أُمَّتِي صلاةً مُخلِصًا مِنْ قَلْبِه؛ صَلَّى اللهُ عليه بها عَشْرَ صلواتٍ، ورَفَعَه بِها عَشْرَ درجاتٍ، وكَتَبَ له بِها عَشْرَ حسناتٍ، ومَحَا عَنْهُ عَشْرَ سيئاتٍ».' WHERE id = 1495;
-- p291
UPDATE contents SET body = 'والمعنى: أنَّكَ إذا صرفتَ جميعَ أزمانِ دعائك في الصلاة عليَّ أُعْطِيتَ مَرَامَ الدنيا والآخِرَةِ، وهذا غايةُ ما يدعو به الإنسانُ من جَلْبِ الخيراتِ، ودَفْعِ المَضَرَّاتِ، فإنَّ الدعاءَ فيه تحصيلُ المطلوبِ، واندفاعُ المرهوب.' WHERE id = 1497;
UPDATE contents SET body = 'عن أميرِ المؤمنين عَلِيٍّ رضي الله عنه، قال رسول الله ﷺ: «كُلُّ دُعاءٍ مَحجُوبٌ حتَّى يُصَلَّى على النبيِّ ﷺ».' WHERE id = 1499;
UPDATE contents SET body = 'وعن أبي علي عمرِو بن مالكٍ الجَنْبِيِّ: أنه سَمِعَ فَضَالَةَ بنَ عُبَيْدٍ يقول: سَمِعَ رسولُ الله ﷺ رجلًا يدعو في صلاته، لم يَحْمَدِ الله، ولم يُصَلِّ على النبيِّ ﷺ، فقال النبيُّ ﷺ: «عَجِلَ هذا». ثُمَّ دعاهُ، فقال له: «إذا صَلَّى أحدُكم فَلْيَبدأْ بتحميدِ الله والثناءِ عليه، ثم لْيُصَلِّ على النبي ﷺ، ثُمَّ لْيَدْعُ بَعْدُ بِما شاء».' WHERE id = 1500;
-- p292
UPDATE contents SET body = 'عن أنسِ بنِ مالكٍ رضي الله عنه، قال رسولُ الله ﷺ: «أكثِرُوا الصلاةَ عَلَيَّ يومَ الجمعةِ وليلةَ الجمعةِ، فَمَنْ صَلَّى عَلَيَّ صلاةً صَلَّى اللهُ عليه عَشْرًا».' WHERE id = 1502;
-- p294
UPDATE contents SET body = 'إنَّ اللهَ -جَلَّتْ حِكْمَتُه- ابتلى الإنسانَ بنفسه الأمَّارة بالسوء، وعدوِّه إبليس، والدنيا الفتانة، لكنه لم يُسْلِمْه لهؤلاءِ، بل أعانَه بِجُنْدٍ آخرينَ يؤزُّونه على الخير، وأمدَّه بمددٍ آخرَ يُقاوِم به هذا الابتلاء: فأرسل إليه رسولَه ﷺ، وأنزل عليه كتابَه، وأيَّده بمَلَكٍ كريم، هو واعظ الله في قلبه، يأمره بأمر ربه، ويبين له ما في طاعةِ عدوِّه من الهلاك.' WHERE id = 1701;
-- p299
UPDATE contents SET body = 'وعن أَغَرَّ مُزَيْنَةَ رضي الله عنه قال رسول الله ﷺ: «إنَّه لَيُغَانُ علَى قَلْبِي، وإنِّي لَأَسْتَغْفِرُ اللهَ في اليَومِ مِئَةَ مَرَّةٍ».' WHERE id = 1117;
UPDATE contents SET body = 'ورُوِيَ عَنْ عَبْدِ الله بنِ عَبَّاسٍ رضي الله عنهما أنَّ رسولَ الله ﷺ قال: «مَن لَزِمَ الاستِغفارَ، جَعَلَ اللهُ له مِن كُلِّ ضِيقٍ مَخرَجًا، ومِن كُلِّ هَمٍّ فَرَجًا، ورَزَقَه مِن حيث لا يَحتَسِبُ».' WHERE id = 1714;
UPDATE contents SET body = 'وعنه رضي الله عنه، قال رسول الله ﷺ: «مَنْ قالَ: (أَستَغفِرُ اللهَ الَّذي لا إلَهَ إلَّا هو، الحَيُّ القَيُّومُ وأَتوبُ إليه) ثلاثًا؛ غُفِرَتْ ذُنوبُه، وإنْ كان فارًّا مِنَ الزَّحْفِ».' WHERE id = 1716;
-- p304
UPDATE contents SET body = '١٧- رَبِّ اغفِرْ لي ﴿خَطِيٓـَٔتِي يَوۡمَ ٱلدِّينِ﴾.' WHERE id = 1734;
-- p305
UPDATE contents SET body = '١٩- اللهُمَّ إنِّي أستغفِرُكَ فاغفِرْ لِي، وأتوبُ إليكَ، فَتُبْ عَلَيَّ.' WHERE id = 1736;
-- p306
UPDATE contents SET body = 'من صِيَغِ الاستغفار في السُّنَّةِ الشَّرِيفَةِ' WHERE id = 1737;
-- p307
UPDATE contents SET body = '٧- اللهم اغفِرْ لي ما قدَّمتُ وما أخَّرتُ، وما أسررتُ وما أعلنتُ، وما أنتَ أعلمُ به مني، إنَّك أنت المُقَدِّمُ والمؤخِّرُ، لا إله إلا أنتَ.' WHERE id = 1744;
UPDATE contents SET body = '٨- لا إله إلا أنت، إني قد ظلمتُ نفسي، فاغفِرْ لِي ذنوبي، إنه لا يغفِرُ الذنوبَ إلا أنتَ.' WHERE id = 1745;
UPDATE contents SET body = '١٠- اللهم اغفِرْ لي خطيئتي وجهلي، وإسرافي في أمري، وما أنتَ أعلمُ به منِّي، اللهم اغفِرْ لِي جِدِّي وهَزْلي، وخطئي وعَمْدِي، وكلُّ ذلك عندي، اللهم اغفِر لي ما قدَّمتُ وما أخَّرتُ، وما أسررتُ وما أعلنتُ، وما أنتَ أعلمُ به منِّي، أنتَ المُقَدِّمُ وأنتَ المؤخِّرُ، وأنتَ على كُلِّ شيءٍ قدير.' WHERE id = 1747;
-- p311
UPDATE contents SET body = 'وعن سَمُرةَ بنِ جُنْدُبٍ رضي الله عنه قال: قال رسولُ الله ﷺ: «أربعٌ هُنَّ مِن أطيَبِ الكلامِ، وهُنَّ من القرآنِ، ولا يضرك بأَيِّهِنَّ بدأتَ: سبحانَ الله، والحمدُ لله، ولا إله إلَّا الله، والله أكبر» الحديث.' WHERE id = 1755;
-- p313
UPDATE contents SET body = 'قال العلَّامةُ الصنعاني رحمه الله: «والأحاديثُ في فضلِ هذه الكلماتِ مجموعة ومتفرِّقة بحرٌ لا تُنْزِفه الدِّلاءُ، ولا يُنْقِصُه الإملاءُ».' WHERE id = 1760;
-- p322
UPDATE contents SET body = '٢٠- سبحان ذي الجبروتِ والملكوتِ والكِبرياءِ والعَظَمَة.' WHERE id = 1803;
-- p326
UPDATE contents SET body = 'وهو سبحانه كما أنه محمودٌ على أسمائه وصفاته فهو محمودٌ على فضله وعطائه ونعمائه لما له على عباده «من جزيل مواهبه، وسَعة عطاياه، وكريم أياديه، وجميل صنائعه، وحسن معاملته لعباده، وسَعةِ رحمته لهم، وبرِّه ولُطفه وحنانه، وإجابته لدعوات المضطرين، وكشف كربات المكروبين، وإغاثة الملهوفين، ورحمته للعالمين، وابتدائه بالنِّعَمِ قبلَ السؤال»، إلى غير ذلك من نعمه وعطائه، وأهم ذلك وأعظمه: «هدايتُه خاصَّتَه وعبادَه إلى سبيل دار السلام، ومدافعته عنهم أحسنَ الدفاع، وحمايتهم عن مراتع الآثام، وأنه حبَّب إليهم الإيمان وزيَّنه في قلوبهم، وكرَّه إليهم الكفرَ والفسوقَ والعِصيانَ، وجعلهم من الراشدين».' WHERE id = 1815;
-- p329
UPDATE contents SET body = 'ثانيًا: في السُّنَّةِ الشَّريفة:' WHERE id = 1830;
-- p331
UPDATE contents SET body = 'قال الحافظُ ابنُ حجرٍ رحمه الله: «التكبيرُ ذكرٌ مأثورٌ عندَ كلِّ أمرٍ مَهُولٍ، وعندَ كُلِّ حادِثِ سرورٍ، شكرًا لله تعالى، وتبرئةً له مِن كل ما نَسَبَ إليه أعداؤه».' WHERE id = 1838;
-- p335
UPDATE contents SET body = 'وهذا داخل في التوحيد لا إله إلا الله، فلا يكون في قلبه لمخلوق شيء من التَّأَلُّه؛ لا قليل ولا كثير، بل التَّألُّه كله لله».' WHERE id = 1851;
-- p336
UPDATE contents SET body = 'وعن جابر بن عبد الله رضي الله عنهما أن رسول الله ﷺ قال: «أُذِنَ لي أن أُحَدِّثَ عن مَلَكٍ من ملائكةِ اللهِ تعالى مِن حَمَلَةِ العرش؛ إنَّ ما بين شَحمةِ أُذُنِهِ إلى عاتقه مسيرة سَبْعِ مِئَةِ عام».' WHERE id = 1854;
UPDATE contents SET body = 'وعن عبد الله بن سلام رضي الله عنه قال رسولُ الله ﷺ: «لا تَفَكَّروا في الله، تَفَكَّروا فيما خَلَقَ اللهُ».' WHERE id = 1855;
-- p341
UPDATE contents SET body = 'فضائل الحولَقَة:' WHERE id = 1868;
-- p345
UPDATE contents SET body = 'وَأَوْلَى ما يُسأل فيه العافية: العافية في الدين، قال ﷺ في دعائه: «ولا تجعَلْ مُصِيبَتَنَا فِي دِينِنا»، وقال ﷺ: «اللهم أَصْلِحْ لي ديني الذي هو عِصْمَةُ أمري».' WHERE id = 1876;
UPDATE contents SET body = 'لا تأسَ من دُنيا على فائتٍ
وعِنْدَكَ الإسلامُ والعافيَهْ
إنْ فَاتَ شيءٌ كنتَ تسعى له
ففيهِما مِن فائتٍ كافيَهْ' WHERE id = 1877;
UPDATE contents SET body = 'ومما يدلُّ على أن الدعاء بالعافية لا يساويه شيء من الأدعية، ولا يقومُ مقامَه شيء من الكلام الذي يُدْعَى به ذو الجلال والإكرام، وأن من أُوتي العافيةَ في الدنيا والآخرة؛ فقد أُوتي الخيرَ بحذافيره، وأن العافية لا يعدِلها شيء:' WHERE id = 1878;
-- p347
UPDATE contents SET body = 'وقال الإمام الشوكاني رحمه الله: «وقد كان رسول الله ﷺ يُنزِلُ عمَّه العباسَ منزلةَ أبيه، ويرى له من الحقِّ ما يراه الولدُ لوالده، ففي تخصيصه بهذا الدعاءِ وقَصْرِه على مجرد الدعاء بالعافية تحريكٌ لِهِمَمِ الراغبين على ملازمته، وأن يجعلوه من أعظم ما يَتوسلون به إلى ربهم سبحانه وتعالى، ويستدفعون به كل ما يُهِمُّهم، ثم كلَّمه ﷺ بقوله: «سَلِ اللهَ العافيةَ في الدنيا والآخرة»، فكان هذا الدعاء من هذه الحيثية قد صار عُدَّةً لدفع كلِّ ضُرٍّ وجَلْبِ كلِّ خيرٍ. اللهم إنا نسألك العافيةَ في الدنيا والآخرة يا أرحمَ الراحمين آمين».' WHERE id = 1882;
-- p350
UPDATE contents SET body = 'وَرُوِيَ عن ابنِ عُمَرَ رضي الله عنهما قال: قال رسولُ الله ﷺ: «مَنْ فُتِحَ لَه مِنْكُم بَابُ الدُّعَاءِ؛ فُتِحَتْ له أبوابُ الرَّحْمَةِ، وما سُئِلَ اللهُ شَيْئًا: أَحَبَّ إِلَيهِ مِنْ أَنْ يُسْأَلَ العافيةَ» الحديثَ.' WHERE id = 1888;
UPDATE contents SET body = 'قال منصورٌ الفقيهُ رحمه الله:
رأيتُ البلاءَ كقَطْرِ السماءِ
وما تُنْبِتُ الأَرْضُ مِن نامِيَهْ
فلا تسألَنَّ إذا ما سَأَلْتَ
إلهَكَ شيئًا سِوى العافيهْ' WHERE id = 1889;
-- p351
UPDATE contents SET body = 'وِرْدُ الدُّعَاءِ بالْعَافِيَة' WHERE id = 1890;
-- p356
UPDATE contents SET body = 'والتوكُّل عمل القلب، والأخذ بالأسباب عملُ الجوارح، فلا يصحُّ التوكُّلُ إلَّا معَ القيامِ بالأسبابِ وعَدَمِ الإخلالِ بها، لكن من تمامه عدم الركون إلى الأسباب وقطع تعلُّق القلب بها، فيكون القلبُ منقطعًا منها متصلًا بالله تعالى، أمَّا الجوارحُ فتشتغِلُ بالأسبابِ، قال ﷺ: «اعقِلْها وتوكَّلْ»، وقال ﷺ: «لو تَوَكَّلْتُم على اللهِ حَقَّ تَوَكُّلِهِ لَرَزَقَكُم كَمَا تُرْزَقُ الطَّيرُ؛ تَغدو خِماصًا، وتَروحُ بِطانًا»، فهي لا تمكثُ في أعشاشها، ولكن تسعى لِرِزْقِها.' WHERE id = 1913;
-- p358
UPDATE contents SET body = 'قال العلامة الطاهر بن عاشور رحمه الله: «في الآية الكريمة إيماءٌ إلى أنَّ الدعاءَ للوالدَيْنِ مُستَجاب؛ لأن الله أَذِنَ فيه».' WHERE id = 1927;
-- p359
UPDATE contents SET body = 'وعن أبي هريرة رضي الله عنه، قال رسول الله ﷺ: «تُرفَع للميتِ بعدَ مَوتِهِ درجةٌ، فيقول: أَيْ رَبِّ، أيُّ شيءٍ هذه؟ فيُقال: ولدُكَ استَغْفَرَ لَكَ». أو «باستغفارِ ولدِكَ لك»، وفي رواية: «بدعاءِ وَلَدِكَ لكْ».' WHERE id = 1929;
UPDATE contents SET body = 'ولقد كانَ السَّلَفُ الصَّالِحُ رحمهم الله يواظِبونَ على الدُّعاءِ للوالدين:' WHERE id = 1930;
-- p362
UPDATE contents SET body = 'النوع الثالثَ عشَرَ: التعوُّذات' WHERE id = 1941;
-- p364
UPDATE contents SET body = 'وتكون الاستعاذة بالله سبحانه كما في قوله تعالى: ﴿ فَٱسۡتَعِذۡ بِٱللَّهِ مِنَ ٱلشَّيۡطَٰنِ ٱلرَّجِيمِ ﴾ [النحل: ٩٨]، وكما في حديثِ الوَلِي: «ولَئِن استعاذَ بِي لأُعِيذَنَّه».' WHERE id = 1951;
-- p365
UPDATE contents SET body = 'ومن التعوُّذِ بِصِفَاتِ الله سُبحانه: قولُ رسولِ الله ﷺ: «اللهم إني أعوذُ برضاك مِن سَخَطِكَ، وبمعافاتكَ من عقوبتك» الحديث.' WHERE id = 1957;
UPDATE contents SET body = 'وأَمَرَ ﷺ رجلًا مريضًا بأنْ يقولَ سبعَ مرَّاتٍ: «أعوذُ بِعِزَّةِ اللهِ وقُدْرَتِه مِن شَرِّ ما أَجِدُ وأُحاذِرُ».' WHERE id = 1958;
UPDATE contents SET body = 'وعن ابنِ عبَّاسٍ رضي الله عنهما قال: كان النبيُّ ﷺ يُعَوِّذُ الحسنَ والحسينَ ويقول: «إنَّ أباكما إبراهيمَ كان يُعَوِّذُ بها إسماعيلَ وإسحاقَ: أُعِيذُكُما بكلماتِ الله التَّامَّةِ من كلِّ شيطانٍ وهامَّةٍ، ومن كُلِّ عينٍ لامَّةٍ».' WHERE id = 1959;
UPDATE contents SET body = 'والمُستعَاذ منه: هو ما يُصِيبُ الإنسانَ من شَرٍّ.' WHERE id = 1960;
-- p367
UPDATE contents SET body = 'التعوُّذُ في السُّنَّةِ الشَّريفَةِ' WHERE id = 1963;
-- p370
UPDATE contents SET body = 'أفضلُ ما يُتَعَوَّذُ بِهِ:' WHERE id = 1976;
UPDATE contents SET body = 'عن ابن عابسٍ الجُهَني -وهو عقبة بن عامر- رضي الله عنه أنَّ رسولَ الله ﷺ قال له: «يا بن عابسٍ، ألا أدُلُّكَ؟» أو قال: «ألا أخبركَ بأفضَلِ ما يتعوَّذُ به المتعوِّذون؟»، قال: بلى يا رسول الله، قال: «﴿ قُلۡ أَعُوذُ بِرَبِّ ٱلۡفَلَقِ ﴾، ﴿ قُلۡ أَعُوذُ بِرَبِّ ٱلنَّاسِ ﴾ هاتين السورتين»، وقال له النبيُّ ﷺ: «ما سألَ سائلٌ بمثلهِما، ولا استعاذَ مُستعيذٌ بمثلهِما».' WHERE id = 1977;
UPDATE contents SET body = 'وسبب ذلك؛ أنَّ هاتين السورتين قد تضمَّنتا الاستعاذة من الشرور كُلِّها بأوجَزِ لفظٍ وأجمعِه، وأدلِّه على المراد، وأعمِّه استعاذةً، بحيثُ لم يبقَ من شَرٍّ من الشرور إلَّا دَخَلَ تحت المستعاذ منه فيهما.' WHERE id = 1979;
-- p372
UPDATE contents SET body = 'لا ريبَ أنَّ مَن تَدَبَّرَ قولَ الله تعالى: ﴿ فَٱذۡكُرُونِيٓ أَذۡكُرۡكُمۡ ﴾ [البقرة: 152]، وقولَه جل وعلا: ﴿ وَمَا خَلَقۡتُ ٱلۡجِنَّ وَٱلۡإِنسَ إِلَّا لِيَعۡبُدُونِ ﴾ [الذاريات: 56]، ثم تأمل قوله ﷺ: «الدُّعاءُ هو العبادةُ»، سطعت له الحجة البينة، والدلالة الواضحة على أنَّ مِن أفضل حالات العباد حالةَ ذكرهم لله رب العالمين، واشتغالهم من صميم الفؤاد، وجميع القلب، بالأذكار المأثورة، والأدعية المستفيضة عن سيد المرسلين، وخاتم النبيين، وخليلِ ربِّ العالمين ﷺ.' WHERE id = 1159;
-- p374
UPDATE contents SET body = 'وقد اجتهدتُ في ترتيبها وتنسيقها، ووزعتها على أحدَ عَشَرَ وِرْدًا حتى يمكنَ تَقسيمُها حسب ظروفِ كل داعٍ، فيأتي ببعضِها في وقت، وببعضها في وقت آخَرَ بحيث يكون مواظبًا على مجموعها غيرَ هاجرٍ لبعضها.' WHERE id = 1161;
-- p375
UPDATE contents SET body = 'وقال زكريا عليه السلام: ﴿ وَلَمۡ أَكُنۢ بِدُعَآئِكَ رَبِّ شَقِيّٗا ﴾ الآية [مريم: 4]، معناه: «لم أزل بدعائك سعيدًا، لم تردُدْه عليَّ»، وقيل: «قد كنتَ عَوَّدْتَني الإجابةَ فيما مضى»، وقيل: «لم أدعُكَ قَطُّ فخيَّبتَني فيما مضى، فَتُخَيِّبَني فيما بقي».' WHERE id = 1525;
-- p376
UPDATE contents SET body = 'وعن ابن عباس، وأبي هريرة، والنعمان بن بشير رضي الله عنهم، قال رسول الله ﷺ: «أفضلُ العبادةِ الدعاء».' WHERE id = 1179;
UPDATE contents SET body = 'وعن أبي هريرة رضي الله عنه، قال رسول الله ﷺ: «ليس شيءٌ أكرمَ على اللهِ تعالى من الدعاء».' WHERE id = 1180;
UPDATE contents SET body = 'وعن ابن عمر رضي الله عنهما قال رسول الله ﷺ: «إن الدعاء ينفع مِمَّا نزل، ومما لم ينزِلْ، فعليكم عبادَ اللهِ بالدعاء».' WHERE id = 1181;
UPDATE contents SET body = 'وعن سلمانَ الفارسيِّ رضي الله عنه، قال رسول الله ﷺ: «إن ربكم حَيِيٌّ كريمٌ يستحيي من عبدِهِ إذا رفع يديه إليه أن يَرُدَّهما صِفْرًا خائبتَيْنِ».' WHERE id = 1182;
UPDATE contents SET body = 'وعنه رضي الله عنه قال رسول الله ﷺ: «لا يَرُدُّ القضاءَ إلَّا الدعاءُ ولَا يَزِيدُ فِي الْعُمُرِ إلَّا البِرُّ».' WHERE id = 1183;
UPDATE contents SET body = 'وإني لأرجو اللهَ حتى كأنني
أرى بجميلِ الظنِّ ما اللهُ صانِعُ' WHERE id = 1526;
-- p377
UPDATE contents SET body = 'وعن أبي هريرة رضي الله عنه قال رسولُ الله ﷺ: «إنَّه مَن لَم يسألِ اللهَ تعالى يغضبْ عليه».' WHERE id = 1184;
UPDATE contents SET body = 'ومع أنَّ الدُّعاءَ وسيلةٌ لِتَحْصِيلِ أَعظَمِ خَيْراتِ الدُّنيا والآخرة وبركاتهما، فإنَّه عبادة سهلة يسيرة لا تُكلِّفُ جُهدًا، ولا تُلحِقُ بالداعي مشقَّةً؛ ولذلك كان التَّواني فيه أشدَّ العَجزِ، ومَن عَجز عنه –مع سهولته– فهو عن غيره أعجَزُ.' WHERE id = 1527;
-- p379
UPDATE contents SET body = '٢- يوم الأربعاء بين صلاتَيِ الظهرِ والعصر.' WHERE id = 1508;
-- p384
UPDATE contents SET body = '٨- اللهم اغفر لِحَيِّنا وَمَيِّتِنا، وشاهِدِنا وغائِبِنا، وصغيرِنا وكبيرِنا، وذَكَرِنَا وأُنثَانا، اللهم من أَحْيَيْتَهُ مِنَّا، فَأَحْيِهِ على الإسلام، ومن توفيتَهُ مِنَّا، فَتَوَفَّهُ على الإيمان.' WHERE id = 1984;
-- p385
UPDATE contents SET body = '١٦- اللهم احفظني بالإسلام قائمًا، واحفظني بالإسلام قاعدًا، واحفظني بالإسلام راقدًا، ولا تُشْمِتْ بي عدوًّا حاسدًا، اللهم إني أسألُكَ مِن كل خيرٍ خزائنُه بيدك، وأعوذ بك من كل شرٍّ خزائنُه بيدك.' WHERE id = 612;
-- p386
UPDATE contents SET body = '١٩- اللهم إنَّك قُلْتَ: ﴿ ٱدۡعُونِيٓ أَسۡتَجِبۡ لَكُمۡۚ ﴾ [غافر: ٦٠]، وإنَّك لا تُخلِفُ الميعادَ، وإنِّي أسألُكَ كما هديتَني للإسلامِ: أن لا تَنْزِعَهُ مِنِّي، حتَّى تتوفَّاني وأنا مُسلِمٌ.' WHERE id = 1989;
UPDATE contents SET body = '٢٠- اللهم ارزقني شهادةً في سبيلِكَ، واجعل موتِي في بَلَدِ رسولِكَ.' WHERE id = 1990;
UPDATE contents SET body = '٢١- اللهم تَوَفَّنِي مَعَ الأبرارِ، ولا تُخَلِّفْني مع الأشرارِ، وأَلْحِقني بالأخيار.' WHERE id = 1991;
UPDATE contents SET body = '٢٢- اللهمَّ صَلِّ على محمدٍ، وعلى آلِ مُحَمَّدٍ، كما صَلَّيْتَ على إبراهيمَ، وعلى آلِ إبراهيمَ، إنَّك حميدٌ مجيد، اللهم بارِكْ على محمدٍ، وعلى آلِ محمدٍ، كما باركتَ على إبراهيمَ، وعلى آلِ إبراهيمَ، إنَّك حميدٌ مجيد.' WHERE id = 1992;
-- p390
UPDATE contents SET body = '٣٤- رَبِّ أَعِنِّي، ولا تُعِنْ عَلَيَّ، وانصُرْني، ولا تَنْصُرْ عَلَيَّ، وامْكُرْ لِي، ولا تَمْكُرْ عَلَيَّ، واهْدِنِي، وَيَسِّرِ الهُدَى لي، وانصرني على مَنْ بَغَى عَلَيَّ، رَبِّ اجعلني لك ذكَّارًا، لكَ شكَّارًا، لك رَهَّابًا، لَكَ مِطْواعًا، لكَ مُخْبِتًا، إليكَ أوَّاهًا مُنِيبًا، رَبِّ تَقَبَّلْ تَوْبَتِي، وَاغْسِلْ حَوْبَتِي، وَأَجِبْ دَعْوَتِي، وثَبِّتْ حُجَّتِي، واهْدِ قَلْبِي، وسَدِّدْ لِساني، واسْلُلْ سَخِيمَةَ صدري.' WHERE id = 769;
-- p392
UPDATE contents SET body = '٤١- اللَّهُمَّ عَلِّمْني الكتابَ، والحِكْمَةَ، وفَقِّهْني في الدِّينِ.' WHERE id = 1995;
-- p395
UPDATE contents SET body = '٤٨- يا ربِّ! أنتَ أنتَ، وأنا أنا، أنتَ العَوَّادُ بالمغفرةِ، وأَنَا العوَّادُ بالذُّنوب.' WHERE id = 1999;
-- p398
UPDATE contents SET body = '٥٤- اللهم إني أسألُكَ من الخيرِ كُلِّهِ، عَاجِلِهِ وآجِلِهِ، مَا عَلِمْتُ منه، وما لم أعلم، وأعوذُ بكَ من الشَّرِّ كُلِّهِ، عَاجِلِهِ وَآجِلِهِ، مَا عَلِمْتُ منه، وما لم أعلمْ، اللهم إني أسألك الجنةَ، وما قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَو عَمَل، وأعوذُ بك من النَّارِ، وما قرَّب إليها من قول أو عمل، اللهم إني أسألك من خير ما سألك عبدُكَ ورسولُك محمد ﷺ، وأعوذ بك من شَرِّ ما استعاذَكَ منه عبدُكَ ورسُولُك محمدٌ ﷺ، وأسألك ما قضيتَ لِي مِنْ أَمْرٍ أن تجعلَ عاقِبَتَهُ لِي رَشَدًا.' WHERE id = 613;
UPDATE contents SET body = '٥٣- اللهم اغفر لي ذنبي كُلَّه، ودِقَّه وجِلَّه، وأولَه وآخِرَه، وعلانِيَتَهُ وسِرَّه.' WHERE id = 2003;
-- p399
UPDATE contents SET body = '٥٧- اللهم إني أسألك فِعْلَ الخيراتِ، وتَرْكَ المنكرات، وحُبَّ المساكين، وأن تغفرَ لي وترحمَني، وإذا أردتَ فِتنةَ قومٍ فتوفَّنِي غَيْرَ مفتونٍ، أسألُكَ حُبَّكَ، وحُبَّ مَنْ يُحِبُّكَ، وحُبَّ عَمَلٍ يُقَرِّبُ إلى حُبِّك.' WHERE id = 632;
UPDATE contents SET body = '٥٦- اللهم إني أعوذ بك من يومِ السُّوء، ومن ليلةِ السُّوء، ومن ساعةِ السوء، ومن صاحبِ السُّوء، ومن جارِ السُّوءِ فِي دَارِ المُقامَةِ.' WHERE id = 799;
-- p404
UPDATE contents SET body = '٧٤- اللهم اجعلْنِي مِفْتَاحًا للخيرِ مِغْلاقًا للشرِّ، ولا تجعلني مِفْتاحًا للشر مِغْلاقًا للخير.' WHERE id = 805;
-- p414
UPDATE contents SET body = '١١٤- اللهم جَنِّبْنِي مُنكَراتِ الأخلاقِ والأهواءِ والأعمالِ والأدواءِ.' WHERE id = 2032;
-- p415
UPDATE contents SET body = '١١٨- اللهم إني أعوذُ بكَ من الجوعِ، فإنه بِئْسَ الضجيعُ، وأعوذ بك من الخيانة، فإنها بِئْسَتِ البِطانةُ.' WHERE id = 694;
UPDATE contents SET body = '١٢٠- اللهم أكثِرْ مالي وولدِي، وبارك لي فيما أعطيتني.' WHERE id = 2035;
-- p419
UPDATE contents SET body = '١٣٤- اللهم اغفِرْ لِي، واجعلني يومَ القيامةِ فوقَ كثيرٍ من خَلْقِكَ.' WHERE id = 2041;
-- p420
UPDATE contents SET body = '١٤٠- اللهم إني أعوذ بك من الكسل والهَرَمِ، والمَغْرَمِ والمأثم، وأعوذ بك من شرِّ المسيح الدجال، وأعوذ بك من عذابِ القبرِ، وأعوذ بك من عذاب النار.' WHERE id = 2046;
-- p422
UPDATE contents SET body = '١٥٢- لا إلهَ إلَّا اللهُ وحدَه، لا شريكَ له، اللهُ أكبرُ كبيرًا، والحمدُ لله كثيرًا، وسبحانَ اللهِ ربِّ العالمين، لا حولَ ولا قوَّةَ إلَّا باللهِ العزيزِ الحكيم، اللَّهُمَّ اغفِرْ لِي، وارحمْنِي، واهدِني، وارزُقْنِي، وعافِني.' WHERE id = 631;
UPDATE contents SET body = '١٥٣- اللهُمَّ حَبِّبْ إِلَيَّ لقاءَكَ، وسَهِّلْ عَلَيَّ قضاءَكَ، وأَقْلِلْ لِي من الدُّنيا.' WHERE id = 2054;
-- p424
UPDATE contents SET body = '١٦٠- اللهُمَّ إنِّي أعوذُ بِوَجْهِكَ الكريمِ، وكلماتِكَ التَّامَّةِ مِنْ شَرِّ ما أنتَ آخِذٌ بناصِيَتِه، اللَّهُمَّ أنتَ تَكْشِفُ المَغْرَمَ والمأثَمَ، اللهُمَّ لا يُهْزَمُ جُنْدُكَ، ولا يُخْلَفُ وَعْدُكَ، ولا يَنْفَعُ ذا الجَدِّ مِنْكَ الجدُّ، سُبحانَكَ اللهُمَّ وبحمدِكَ.' WHERE id = 2059;
-- p425
UPDATE contents SET body = '١٦٣- اللهُمَّ إنِّي أعوذُ بِكَ من جارِ السُّوءِ، ومن زوجٍ تُشَيِّبُني قبلَ المشيب، ومن ولَدٍ يكونُ عَلَيَّ رَبًّا، ومن مالٍ يكونُ عَلَيَّ عذابًا، ومن خليلٍ ماكرٍ عينُه تراني، وقلبُه يَرْعاني؛ إن رأى حَسَنَةً دفَنَها، وإذا رأى سيئةً أذاعَها.' WHERE id = 2062;
-- p427
UPDATE contents SET body = '١٧٠- اللهم فَقِّهْنِي في الدِّين، وعَلِّمْني التأويل.' WHERE id = 2067;
-- p428
UPDATE contents SET body = '١٧٤- الحمدُ لله الذي كَفاني وآواني، وأطعَمَنِي وأسْقَاني، والذي مَنَّ عَلَيَّ فأَفضَلَ، والذي أعطاني فأَجْزَلَ، الحمدُ للهِ على كُلِّ حالٍ، اللهم ربَّ كُلِّ شيءٍ ومَلِيكَه، وإلهَ كُلِّ شيءٍ، أعوذُ بك من النار.' WHERE id = 2069;
-- p430
UPDATE contents SET body = '١٧٨- اللهم اغفر لي ذنوبي وخطاياي كُلَّها، اللهم أَنْعِشْنِي، واجْبُرْنِي، واهدني لصالحِ الأعمالِ والأخلاق، فإنه لا يَهْدِي لصالحِها، ولا يَصْرِفُ سَيِّئَها إلا أنت.' WHERE id = 772;
-- p431
UPDATE contents SET body = '١٨٣- اللهُمَّ إني أسألُكَ إيمانًا لا يرتدُّ، ونعيمًا لا ينفدُ، ومُرافقةَ نبيِّكَ محمدٍ ﷺ في أعلى جَنَّةِ الخُلْدِ.' WHERE id = 2074;
-- p435
UPDATE contents SET body = '١٩٤- اللهم إني أسألك بأن لك الحمدَ، لا إله إلا أنت وحدك لا شريك لك، المنانُ، يا بديعَ السماواتِ والأرض، يا ذا الجلالِ والإكرامِ، يا حيُّ يا قيُّومُ، إني أسألُك الجنةَ، وأعوذُ بك من النار.' WHERE id = 650;
UPDATE contents SET body = '١٩٣- ربنا لك الحمدُ، مِلْءَ السماوات، ومِلْءَ الأرضِ، ومِلْءَ ما بينهما، ومِلْءَ مَا شِئْتَ من شيءٍ بَعْدُ، أَهْلَ الثناءِ والمجدِ، أَحَقُّ ما قال العبدُ، وكُلُّنا لك عبد، اللهم لا مانِعَ لما أعطيتَ، ولا مُعْطِيَ لما منعتَ، ولا ينفعُ ذا الجَدِّ مِنكَ الجَدُّ.' WHERE id = 2080;
-- p436
UPDATE contents SET body = '٢٠١- يا مُقَلِّبَ القلوبِ ثَبِّتْ قلبي على دِينِك.' WHERE id = 859;
-- p437
UPDATE contents SET body = '٢٠٤- اللهم إني أعوذ بك من شَرِّ جارِ السُّوءِ في دارِ المُقام.' WHERE id = 731;
UPDATE contents SET body = '٢٠٣- اللهم مَتِّعْنِي بسمعي وبصري، واجعلْهُما الوارِثَ مِنِّي، وانْصُرْنِي على مَن ظلمني، وخُذْ منه بثأري.' WHERE id = 804;
UPDATE contents SET body = '٢٠٢- يا وليَّ الإسلامِ وأهلِه، ثَبِّتْنِي به حتى ألقاك.' WHERE id = 2086;
-- p438
UPDATE contents SET body = '٢٠٨- تَمَّ نورُكَ فهديتَ فلك الحمد، وعَظُمَ حِلْمُكَ فعفوتَ فلك الحمد، وبسطتَ يدَكَ فأعطيتَ فلك الحمد، ربَّنا وجهُكَ أكرمُ الوجوهِ، وجاهُكَ خيرُ الجاهِ، وعَطِيَّتُكَ أفضلُ العَطِيَّة، وأهنؤها، تُطاعُ رَبَّنَا فَتَشْكُرُ، وتُعصَى ربنا فتغفِر، تُجِيبُ المضْطَرَّ، وتكشِفُ الضُّرَّ، وتَشْفي السقيمَ، وتُنَجِّي مِنَ الكَرْبِ، وتقبلُ التوبةَ، وتغفر الذنبَ لمن شِئتَ، لا يَجْزِي بآلائك أحدٌ، ولا يُحصِي نَعْماءَكَ قولُ قائل.' WHERE id = 2090;
-- p441
UPDATE contents SET body = '٢٢٤- اللهم لك الحمدُ، مِلْءَ السماواتِ، ومِلْءَ الأرضِ، ومِلْءَ ما شِئتَ مِن شيءٍ بعدُ، اللهم طَهِّرْني بالثلج والبَرَد والماء البارد، اللهم طَهِّرني من الذنوب والخطايا كما يُنَقَّى الثوبُ الأبيضُ من الدَّنَسِ.' WHERE id = 2098;
-- p442
UPDATE contents SET body = '٢٢٧- اللهم إنا نسألُكَ أن تستُرَ عَوراتِنا، وتُؤَمِّنَ رَوْعاتِنا.' WHERE id = 696;
-- p443
UPDATE contents SET body = '٢٣٥- اللهم رَبَّ جبرائيلَ وميكائيلَ، وربَّ إسرافيلَ، أعوذُ بِك من حَرِّ النار، وعذابِ القبر.' WHERE id = 798;
UPDATE contents SET body = 'اللهم إنِّي أعوذُ بِكَ من النار. [ثلاثًا]' WHERE id = 851;

PRAGMA user_version = 166;
COMMIT;
